import { container } from '@/infrastructure/di/container';
import { getAuthenticatedToken } from '@/lib/utils/authUtils';
import { Result } from '@/lib/utils/result';
import type { User as FirebaseUser } from 'firebase/auth';

type ClientConstructor<TClient> = new (...args: never[]) => TClient;

const getAuthenticationError = (): Error => new Error('User not authenticated');

export const runAuthenticatedClientCall = async <TClient, TResult>(
  firebaseUser: FirebaseUser | null | undefined,
  clientClass: ClientConstructor<TClient>,
  callback: (client: TClient, token: string) => Promise<TResult>,
): Promise<TResult> => {
  if (!firebaseUser) {
    throw getAuthenticationError();
  }

  const token = await getAuthenticatedToken(firebaseUser);
  const client = container.resolve(clientClass);

  return callback(client, token);
};

export const unwrapResult = <TValue, TError>(result: Result<TValue, TError>): TValue => {
  if (result.isFailure) {
    if (result.error instanceof Error) {
      throw result.error;
    }

    throw new Error('API client call failed');
  }

  return result.getValue();
};

export const runAuthenticatedResultCall = async <TClient, TValue, TError>(
  firebaseUser: FirebaseUser | null | undefined,
  clientClass: ClientConstructor<TClient>,
  callback: (client: TClient, token: string) => Promise<Result<TValue, TError>>,
): Promise<TValue> => {
  const result = await runAuthenticatedClientCall(firebaseUser, clientClass, callback);
  return unwrapResult(result);
};
"}

{"file_path":"src/modules/users/adapters/api-client/UserApiClient.ts","overwrite":true,"initial_content":"import { injectable } from 'tsyringe';
import { apiService, ApiError } from '@/infrastructure/api/ApiService';
import { Result } from '@/lib/utils/result';
import type { UserProfile, UserRole } from '../../domain/entities/User';
import { doc, onSnapshot, type Firestore } from 'firebase/firestore';

export interface PaginatedUsersResponse {
  users: UserProfile[];
  hasNextPage: boolean;
  lastVisibleId: string | null;
}

export interface CreateUserInput {
  name: string;
  email: string;
  password: string;
  role: UserRole;
  credits: number;
}

export interface CreateUserResponse {
  user: {
    uid: string;
    email?: string;
  };
}

export interface SendNotificationInput {
  userId: string;
  title: string;
  body: string;
  link?: string;
}

export interface SendNotificationResponse {
  message?: string;
  messageId?: string;
}

const toApiError = (error: unknown): ApiError => {
  if (error instanceof ApiError) {
    return error;
  }

  return new ApiError('Unexpected API client error', 500, error);
};

@injectable()
export class UserApiClient {
  async fetchUserById(id: string, token: string): Promise<Result<UserProfile, ApiError>> {
    try {
      const data = await apiService<never, UserProfile>({ endpoint: `/api/users/${id}`, token });
      return Result.ok(data);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  async fetchUserProfile(id: string, token: string): Promise<Result<UserProfile, ApiError>> {
    return this.fetchUserById(id, token);
  }

  async updateUser(id: string, data: Partial<UserProfile>, token: string): Promise<Result<UserProfile, ApiError>> {
    try {
      const response = await apiService<Partial<UserProfile>, UserProfile>({
        endpoint: `/api/users/${id}`,
        method: 'PUT',
        data,
        token,
      });

      return Result.ok(response);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  async getPaginatedUsers(
    options: { limit: number; lastVisibleId?: string },
    token: string,
  ): Promise<Result<PaginatedUsersResponse, ApiError>> {
    try {
      const params = new URLSearchParams();
      params.append('limit', options.limit.toString());
      if (options.lastVisibleId) {
        params.append('lastVisibleId', options.lastVisibleId);
      }

      const response = await apiService<never, PaginatedUsersResponse>({
        endpoint: `/api/admin/users?${params.toString()}`,
        token,
      });

      return Result.ok(response);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  async createUser(data: CreateUserInput, token: string): Promise<Result<CreateUserResponse, ApiError>> {
    try {
      const response = await apiService<CreateUserInput, CreateUserResponse>({
        endpoint: '/api/admin/users',
        method: 'POST',
        data,
        token,
      });

      return Result.ok(response);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  async adminUpdateUser(id: string, data: Partial<UserProfile>, token: string): Promise<Result<UserProfile, ApiError>> {
    try {
      const response = await apiService<Partial<UserProfile>, UserProfile>({
        endpoint: `/api/admin/users/${id}`,
        method: 'PUT',
        data,
        token,
      });

      return Result.ok(response);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  async deleteUser(id: string, token: string): Promise<Result<{ message: string }, ApiError>> {
    try {
      const response = await apiService<never, { message: string }>({
        endpoint: `/api/admin/users/${id}`,
        method: 'DELETE',
        token,
      });

      return Result.ok(response);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  async sendNotification(
    variables: SendNotificationInput,
    token: string,
  ): Promise<Result<SendNotificationResponse, ApiError>> {
    try {
      const response = await apiService<SendNotificationInput, SendNotificationResponse>({
        endpoint: '/api/admin/notifications/send',
        method: 'POST',
        data: variables,
        token,
      });

      return Result.ok(response);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  subscribeToUserProfile(
    userId: string,
    firestore: Firestore,
    callback: (user: UserProfile | null) => void,
  ): () => void {
    if (typeof window === 'undefined' || !firestore) {
      return () => {};
    }

    const userDocRef = doc(firestore, 'users', userId);

    const unsubscribe = onSnapshot(
      userDocRef,
      (snapshot) => {
        if (snapshot.exists()) {
          callback({ id: snapshot.id, ...snapshot.data() } as UserProfile);
          return;
        }

        callback(null);
      },
      (error) => {
        console.error('Error listening to user profile:', error);
        callback(null);
      },
    );

    return unsubscribe;
  }
}
"}

{"file_path":"src/hooks/data/use-users.ts","overwrite":true,"initial_content":"'use client';

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { userKeys } from '@/lib/query-keys';
import { handleErrorUtility } from '@/lib/utils/errorUtils';
import { useAuth } from '@/context/AuthContext';
import { toast } from '@/hooks';
import {
  UserApiClient,
  type CreateUserInput,
  type CreateUserResponse,
  type SendNotificationInput,
} from '@/modules/users/adapters/api-client/UserApiClient';
import { User, type UserProfile } from '@/modules/users/domain/entities/User';
import { runAuthenticatedResultCall } from './authenticated-client-call';

export function useUserProfile(userId: string) {
  const { firebaseUser } = useAuth();

  return useQuery({
    queryKey: userKeys.profile(userId),
    queryFn: async () => {
      if (!firebaseUser) {
        return null;
      }

      const userProfile = await runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) =>
        client.fetchUserById(userId, token),
      );

      return userProfile ? new User(userProfile) : null;
    },
    enabled: Boolean(firebaseUser && userId),
  });
}

export function useCreateUser(options?: { onSuccess?: (data: CreateUserResponse) => void }) {
  const queryClient = useQueryClient();
  const { firebaseUser } = useAuth();

  return useMutation({
    mutationFn: async (data: CreateUserInput) =>
      runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) => client.createUser(data, token)),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: userKeys.lists() });
      options?.onSuccess?.(data);
    },
    onError: (error) => handleErrorUtility(error, 'Create User Failed'),
  });
}

export function useUpdateUser() {
  const queryClient = useQueryClient();
  const { firebaseUser } = useAuth();

  return useMutation({
    mutationFn: async (variables: { userId: string; data: Partial<UserProfile> }) =>
      runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) =>
        client.updateUser(variables.userId, variables.data, token),
      ),
    onSuccess: (data) => {
      toast({ title: 'Success', description: 'User profile has been successfully updated.' });
      queryClient.invalidateQueries({ queryKey: userKeys.lists() });
      queryClient.invalidateQueries({ queryKey: userKeys.profile(data.id) });
    },
    onError: (error) => handleErrorUtility(error, 'Update Failed'),
  });
}

export function useAdminUpdateUser() {
  const queryClient = useQueryClient();
  const { firebaseUser } = useAuth();

  return useMutation({
    mutationFn: async (variables: { userId: string; data: Partial<UserProfile> }) =>
      runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) =>
        client.adminUpdateUser(variables.userId, variables.data, token),
      ),
    onSuccess: (data) => {
      toast({ title: 'Success', description: 'User profile has been successfully updated.' });
      queryClient.invalidateQueries({ queryKey: userKeys.lists() });
      queryClient.invalidateQueries({ queryKey: userKeys.profile(data.id) });
    },
    onError: (error) => handleErrorUtility(error, 'Update Failed'),
  });
}

export function useDeleteUser() {
  const queryClient = useQueryClient();
  const { firebaseUser } = useAuth();

  return useMutation({
    mutationFn: async (userId: string) =>
      runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) => client.deleteUser(userId, token)),
    onSuccess: (_data, userId) => {
      toast({ title: 'User Deleted', description: `User with ID ${userId} has been removed.` });
      queryClient.invalidateQueries({ queryKey: userKeys.lists() });
    },
    onError: (error) => handleErrorUtility(error, 'Delete Failed'),
  });
}

export function useSendNotification() {
  const { firebaseUser } = useAuth();

  return useMutation({
    mutationFn: async (variables: SendNotificationInput) =>
      runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) =>
        client.sendNotification(variables, token),
      ),
    onSuccess: () => {
      toast({ title: 'Notification Sent', description: 'The user has been notified of the changes.' });
    },
    onError: (error: unknown) => {
      let errorMessage = 'Failed to send notification.';

      if (error instanceof Error && !error.message.includes('token not found')) {
        errorMessage = error.message;
      }

      toast({ title: 'Notification Error', description: errorMessage, variant: 'destructive' });
    },
  });
}
"}

{"file_path":"src/hooks/data/use-projects.ts","overwrite":true,"initial_content":"'use client';

import { toast } from '@/hooks/util/use-toast';
import { projectKeys } from '@/lib/query-keys';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useBuilderStore } from '../core/useBuilderStore';
import { useAuth } from '@/context/AuthContext';
import { LocalProjectService } from '@/modules/projects/adapters/local-storage/LocalProjectService';
import { ProjectApiClient } from '@/modules/projects/adapters/api-client/ProjectApiClient';
import { Project, type ProjectProperties } from '@/modules/projects/domain/entities/Project';
import { container } from '@/infrastructure/di/container';
import { runAuthenticatedResultCall } from './authenticated-client-call';

export function useProjects() {
  const { firebaseUser } = useAuth();
  const projectScope = firebaseUser?.uid ?? 'anonymous';

  const { data, ...rest } = useQuery<Project[]>({
    queryKey: projectKeys.lists(projectScope),
    queryFn: async () => {
      if (!firebaseUser) {
        return [];
      }

      try {
        const serverProjects = await runAuthenticatedResultCall(firebaseUser, ProjectApiClient, (client, token) =>
          client.fetchProjects(token),
        );
        const localService = container.resolve(LocalProjectService);
        const mergedProjects = serverProjects.map((project) => new Project(project));

        mergedProjects.forEach((project) => {
          localService.saveProject(project.toStateObject());
        });

        return mergedProjects;
      } catch (error) {
        console.warn('Could not sync with server, using local projects.', error);
        const localService = container.resolve(LocalProjectService);
        const localProjects = await localService.getAllProjects();
        return localProjects.map((project: ProjectProperties) => new Project(project));
      }
    },
    enabled: Boolean(firebaseUser),
  });

  return { projects: data, ...rest };
}

export function useSaveProject() {
  const queryClient = useQueryClient();
  const { setHasUnsavedChanges } = useBuilderStore();
  const { firebaseUser } = useAuth();
  const projectScope = firebaseUser?.uid ?? 'anonymous';

  const saveProjectMutation = useMutation({
    mutationFn: async (projectData: ProjectProperties) => {
      if (!navigator.onLine || !firebaseUser) {
        toast({
          title: 'Offline',
          description: 'You are offline. Please connect to the internet to save the project.',
          variant: 'destructive',
        });
        throw new Error('User is offline.');
      }

      return runAuthenticatedResultCall(firebaseUser, ProjectApiClient, (client, token) =>
        client.saveProject(projectData, token),
      );
    },
    onSuccess: (savedProject) => {
      setHasUnsavedChanges(false);
      queryClient.invalidateQueries({ queryKey: projectKeys.lists(projectScope) });
      toast({ title: 'Project Saved', description: `"${savedProject.name}" has been saved to the cloud.` });
    },
    onError: (error: unknown) => {
      const description = error instanceof Error ? error.message : 'Failed to save project.';
      toast({ title: 'Error', description: `Failed to save project: ${description}`, variant: 'destructive' });
    },
  });

  return {
    saveProjectMutation,
    isSaving: saveProjectMutation.isPending,
  };
}

export function useDeleteProject() {
  const queryClient = useQueryClient();
  const { firebaseUser } = useAuth();
  const projectScope = firebaseUser?.uid ?? 'anonymous';

  return useMutation({
    mutationFn: async (projectId: string) => {
      const localService = container.resolve(LocalProjectService);
      const localDelete = localService.deleteProject(projectId);

      if (navigator.onLine && firebaseUser) {
        try {
          await runAuthenticatedResultCall(firebaseUser, ProjectApiClient, (client, token) =>
            client.deleteProject(projectId, token),
          );
        } catch (error) {
          console.error('Failed to delete from server:', error);
        }
      }

      await localDelete;
      return projectId;
    },
    onSuccess: (projectId) => {
      toast({ title: 'Project Deleted', description: 'The project has been successfully deleted.' });
      queryClient.invalidateQueries({ queryKey: projectKeys.lists(projectScope) });
      queryClient.removeQueries({ queryKey: projectKeys.detail(projectId) });
    },
    onError: (error: unknown) => {
      const description = error instanceof Error ? error.message : 'Delete failed.';
      toast({ title: 'Delete Failed', description, variant: 'destructive' });
    },
  });
}
"}

