import { useInfiniteQuery } from '@tanstack/react-query';
import { userKeys } from '@/lib/query-keys';
import { useAuth } from '@/context/AuthContext';
import { User } from '@/modules/users/domain/entities/User';
import { UserApiClient } from '@/modules/users/adapters/api-client/UserApiClient';
import { runAuthenticatedResultCall } from '@/hooks/data/authenticated-client-call';

const USERS_PER_PAGE = 10;

export function useUserManagementConsole() {
  const { firebaseUser, isLoading: authLoading } = useAuth();

  const {
    data,
    error,
    fetchNextPage,
    hasNextPage,
    isFetching,
    isFetchingNextPage,
    isLoading: usersLoading,
    isError,
  } = useInfiniteQuery({
    queryKey: userKeys.lists(),
    queryFn: async ({ pageParam }) => {
      const result = await runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) =>
        client.getPaginatedUsers({ limit: USERS_PER_PAGE, lastVisibleId: pageParam }, token),
      );

      return {
        ...result,
        users: result.users.map((user) => new User(user)),
      };
    },
    initialPageParam: undefined as string | undefined,
    getNextPageParam: (lastPage) => (lastPage.hasNextPage ? lastPage.lastVisibleId ?? undefined : undefined),
    enabled: !authLoading && Boolean(firebaseUser),
    staleTime: 1000 * 60 * 5,
  });

  const allUsers = data?.pages.flatMap((page) => page.users) ?? [];

  return {
    allUsers,
    error,
    fetchNextPage,
    hasNextPage,
    isFetching,
    isFetchingNextPage,
    isLoading: usersLoading || authLoading,
    isError,
  };
}
"}

{"file_path":"src/context/AuthContext.tsx","overwrite":true,"initial_content":"'use client';

import { userKeys } from '@/lib/query-keys';
import { manageSession } from '@/lib/utils/session-management';
import { hasGuestCookie, clearGuestCookie } from '@/lib/utils/cookie-management';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { container } from '@/infrastructure/di/container';
import { UserApiClient } from '@/modules/users/adapters/api-client/UserApiClient';
import { User } from '@/modules/users/domain/entities/User';
import { User as FirebaseUser, onAuthStateChanged } from 'firebase/auth';
import { createContext, ReactNode, useCallback, useContext, useEffect, useState } from 'react';
import { useBuilderStore } from '@/hooks';
import { useAuth as useFirebaseAuth, useFirestore } from '@/firebase/provider';
import { runAuthenticatedResultCall } from '@/hooks/data/authenticated-client-call';

interface AuthContextType {
  firebaseUser: FirebaseUser | null;
  userProfile: User | null;
  isLoading: boolean;
  isGuest: boolean;
  refetchUser: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const auth = useFirebaseAuth();
  const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
  const [authIsLoading, setAuthIsLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);
  const queryClient = useQueryClient();
  const { setUserProfile } = useBuilderStore();
  const firestore = useFirestore();

  useEffect(() => {
    if (firebaseUser?.uid && firestore) {
      const client = container.resolve(UserApiClient);
      const unsubscribe = client.subscribeToUserProfile(firebaseUser.uid, firestore, (user) => {
        const userInstance = user ? new User(user) : null;
        queryClient.setQueryData(userKeys.profile(firebaseUser.uid), userInstance);
        setUserProfile(userInstance);
      });

      return () => unsubscribe();
    }

    if (!firebaseUser) {
      setUserProfile(null);
    }
  }, [firebaseUser, queryClient, setUserProfile, firestore]);

  const { data: userProfile, isLoading: isProfileLoading } = useQuery<User | null>({
    queryKey: userKeys.profile(firebaseUser?.uid ?? ''),
    queryFn: async () => {
      if (!firebaseUser) {
        return null;
      }

      const userProfileData = await runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) =>
        client.fetchUserById(firebaseUser.uid, token),
      );
      const userInstance = userProfileData ? new User(userProfileData) : null;
      setUserProfile(userInstance);
      return userInstance;
    },
    enabled: Boolean(firebaseUser),
    staleTime: Infinity,
  });

  const refetchUser = useCallback(() => {
    if (firebaseUser?.uid) {
      queryClient.invalidateQueries({ queryKey: userKeys.profile(firebaseUser.uid) });
    }
  }, [firebaseUser, queryClient]);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setFirebaseUser(user);
      await manageSession(user as never);

      const guestCookieExists = hasGuestCookie();

      if (user) {
        setIsGuest(false);
        if (guestCookieExists) {
          clearGuestCookie();
        }
        await queryClient.invalidateQueries({ queryKey: userKeys.profile(user.uid) });
      } else {
        setIsGuest(guestCookieExists);
        if (!guestCookieExists) {
          queryClient.clear();
          setUserProfile(null);
        }
      }

      setAuthIsLoading(false);
    });

    return () => unsubscribe();
  }, [auth, queryClient, setUserProfile]);

  const value = {
    firebaseUser,
    userProfile: userProfile ?? null,
    isLoading: authIsLoading || (Boolean(firebaseUser) && isProfileLoading),
    isGuest,
    refetchUser,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export type { FirebaseUser };
"}

{"file_path":"src/lib/query-keys.ts","overwrite":true,"initial_content":"/**
 * Query Key Factories for React Query
 *
 * This file centralizes the creation of query keys to ensure consistency
 * and prevent typos. Using factories makes it easy to manage complex
 * keys and invalidate queries from anywhere in the application.
 *
 * @see https://tkdodo.eu/blog/effective-react-query-keys
 */

export const userKeys = {
  all: () => ['users'] as const,
  lists: () => [...userKeys.all(), 'list'] as const,
  list: (page: number) => [...userKeys.lists(), { page }] as const,
  details: () => [...userKeys.all(), 'detail'] as const,
  profile: (userId: string) => [...userKeys.details(), userId] as const,
  admins: () => [...userKeys.all(), 'admins'] as const,
};

export const featureKeys = {
  all: () => ['features'] as const,
  lists: () => [...featureKeys.all(), 'list'] as const,
  details: () => [...featureKeys.all(), 'detail'] as const,
  detail: (featureId: string) => [...featureKeys.details(), featureId] as const,
};

export const transactionKeys = {
  all: () => ['transactions'] as const,
  lists: () => [...transactionKeys.all(), 'list'] as const,
  list: (identifier: 'pending' | 'verified' | 'rejected' | string) => [...transactionKeys.lists(), { identifier }] as const,
};

export const generationLogKeys = {
  all: () => ['generation-logs'] as const,
  lists: () => [...generationLogKeys.all(), 'list'] as const,
  list: (filters: { agentId?: string; userId?: string }) => [...generationLogKeys.lists(), filters] as const,
};

export const adminKeys = {
  all: () => ['admin'] as const,
  dashboardStats: () => [...adminKeys.all(), 'dashboard-stats'] as const,
};

export const analyticsKeys = {
  all: () => ['analytics'] as const,
  userStats: (userId: string) => [...analyticsKeys.all(), 'user-stats', userId] as const,
};

export const projectKeys = {
  all: (userId: string) => ['projects', userId] as const,
  lists: (userId: string) => [...projectKeys.all(userId), 'list'] as const,
  details: (userId: string) => [...projectKeys.all(userId), 'detail'] as const,
  detail: (userId: string, projectId: string) => [...projectKeys.details(userId), projectId] as const,
};

export const homeworkKeys = {
  all: () => ['homework'] as const,
  history: (userId?: string) => [...homeworkKeys.all(), 'history', userId] as const,
};

export const notificationKeys = {
  all: () => ['notifications'] as const,
  lists: () => [...notificationKeys.all(), 'list'] as const,
};

export const sectionKeys = {
  all: () => ['sections'] as const,
  lists: () => [...sectionKeys.all(), 'list'] as const,
  detail: (id: string) => [...sectionKeys.all(), 'detail', id] as const,
};

export const agentKeys = {
  all: () => ['agents'] as const,
};

export const templateKeys = {
  all: () => ['templates'] as const,
  docx: () => [...templateKeys.all(), 'docx'] as const,
  pptx: () => [...templateKeys.all(), 'pptx'] as const,
  report: () => [...templateKeys.all(), 'report'] as const,
  presentation: () => [...templateKeys.all(), 'presentation'] as const,
};

export const writingToolKeys = {
  all: () => ['writing-tools'] as const,
  tool: (name: string) => [...writingToolKeys.all(), name] as const,
};
"}

{"file_path":"src/modules/templates/adapters/api-client/TemplateApiClient.ts","overwrite":true,"initial_content":"import { injectable } from 'tsyringe';
import { apiService, ApiError } from '@/infrastructure/api/ApiService';
import { Result } from '@/lib/utils/result';
import type { DocxTemplateProperties } from '@/modules/templates/domain/entities/DocxTemplate';
