{"file_path":"src/hooks/data/__tests__/use-users.test.tsx","overwrite":true,"initial_content":"import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, renderHook, waitFor } from '@testing-library/react';
import { User } from '@/modules/users/domain/entities/User';
import { userKeys } from '@/lib/query-keys';
import { useCreateUser, useUserProfile, useUpdateUser } from '../use-users';

jest.mock('@/context/AuthContext', () => ({
  useAuth: jest.fn(),
}));

jest.mock('@/hooks', () => ({
  toast: jest.fn(),
}));

jest.mock('@/lib/utils/errorUtils', () => ({
  handleErrorUtility: jest.fn(),
}));

jest.mock('@/hooks/data/authenticated-client-call', () => ({
  runAuthenticatedResultCall: jest.fn(),
}));

const { useAuth } = jest.requireMock('@/context/AuthContext') as {
