  31 export function useExport() {
  32     const [isExporting, setIsExporting] = useState(false);
  33 
  34     /**
  35      * Exports a report as a DOCX file by calling the server-side API.
  36      * The server now handles markdown generation from the project object.
  37      * @param params - An object containing the project, export options, and selected content.
  38      */
  39     const exportReportDocx = async ({ project, options, selectedContent }: DocxExportParams) => {
  40         if (selectedContent.length === 0) {
  41             toast({ title: 'Export Canceled', description: 'No content selected to export.', variant: 'destructive' });
  42             return;
  43         }
  44         setIsExporting(true);
  45         try {
  46             const templateStyles = docxTemplates[options.template] || docxTemplates.modern;
  47             
  48             const apiOptions: Omit<ConversionOptions, 'coverPageMarkdown'> = {
  49                 styles: templateStyles.styles,
  50                 customStyles: templateStyles.customStyles,
  51                 pageNumbers: options.pageNumbers,
  52                 isRtl: false, // Defaulting to LTR for now
  53             };
  54 
  55             const selectedContentPlain = selectedContent.map(item => item.toStateObject());
  56 
  57             const response = await fetch('/api/export/docx', {
  58                 method: 'POST',
  59                 headers: { 'Content-Type': 'application/json' },
  60                 body: JSON.stringify({
  61                     project: project.toStateObject(),
  62                     selectedContent: selectedContentPlain,
  63                     options: apiOptions,
  64                 }),
  65             });
  66 
  67             if (!response.ok) {
  68                 let errorMessage = 'Failed to generate DOCX file on the server.';
  69                 try {
  70                     const errorData = await response.json();
  71                     if (typeof errorData === 'string') {
  72                         errorMessage = errorData;
  73                     } else if (errorData && errorData.message) {
  74                         errorMessage = errorData.message;
  75                         // Include additional error details if available
  76                         if (errorData.error) {
  77                             errorMessage += `\n\nDetails: ${errorData.error}`;
  78                         }
  79                     }
  80                 } catch {
  81                     // If response is not JSON, use status text
  82                     errorMessage = `Server error: ${response.statusText || response.status}`;
  83                 }
  84                 throw new Error(errorMessage);
  85             }
  86 
  87             const blob = await response.blob();
  88             saveAs(blob, `${project.name.replace(/\s+/g, '_')}_report.docx`);
  89 
  90             toast({ title: 'Export Successful', description: 'Report exported as DOCX.' });
  91         } catch (error) {
  92             console.error('DOCX Export Error:', error);
  93             const errorMessage = error instanceof Error ? error.message : 'Could not generate the DOCX file.';
  94             toast({ 
  95                 title: 'Export Failed', 
  96                 description: errorMessage, 
  97                 variant: 'destructive',
  98                 duration: 7000 // Show error longer for user to read
  99             });
 100         } finally {
 101             setIsExporting(false);
 102         }
 103     };
