 118             const templateStyles = pptxTemplates[options.template] || pptxTemplates.modern;
 119             const client = container.resolve<any>(IPptxExportServiceToken);
 120             
 121             const result = await client.export(project, selectedContent, {
 122                 styles: templateStyles.styles,
 123                 isRtl: options.isRtl,
 124                 includeToc: options.includeToc,
 125             });
 126 
 127             const blob = result instanceof Blob ? result : new Blob([result as any], { 
 128                 type: 'application/vnd.openxmlformats-officedocument.presentationml.presentation' 
 129             });
 130             saveAs(blob, `${project.name.replace(/\s+/g, '_')}_presentation.pptx`);
 131 
 132             toast({ title: 'Export Successful', description: 'Presentation exported as PPTX.' });
 133         } catch (error) {
