  22  */
  23 export function useFileUpload(
  24   setValue: UseFormSetValue<any>,
  25   options: UseFileUploadOptions = {}
  26 ) {
  27   const { 
  28     onSuccess, 
  29     onError, 
  30     fieldName = 'text',
  31     acceptedFormats = {
