  39   const { firebaseUser, refetchUser } = useAuth();
  40   const { toast } = useToast();
  41 
  42   const onDrop = useCallback(async (acceptedFiles: File[]) => {
  43     const file = acceptedFiles[0];
  44     if (!file) return;
  45 
  46     if (!firebaseUser) {
  47       const errorMsg = "You must be logged in to process files.";
  48       toast({ 
