  65       
  66       setValue(fieldName, result.markdown, { shouldValidate: true });
  67       
  68       const successMsg = `Text extracted from ${file.name}.`;
  69       toast({ 
  70         title: "File Processed", 
  71         description: successMsg 
  72       });
  73       
  74       onSuccess?.(file.name);
  75       refetchUser();
  76     } catch (error: any) {
  77       const errorMsg = error.message || "Failed to process file";
  78       toast({ 
  79         title: "File Processing Failed", 
  80         description: errorMsg, 
  81         variant: "destructive" 
  82       });
  83       onError?.(errorMsg);
  84     } finally {
  85       setIsUploading(false);
  86     }
  87   }, [firebaseUser, setValue, fieldName, refetchUser, toast, onSuccess, onError]);
  88 
  89   const { getRootProps, getInputProps, isDragActive } = useDropzone({
