  24     async readFileContent(file: File): Promise<string> {
  25     return new Promise((resolve, reject) => {
  26         const reader = new FileReader();
  27 
  28         reader.onabort = () => reject(new Error('File reading was aborted.'));
  29         reader.onerror = () => reject(new Error('Failed to read file.'));
  30         reader.onload = () => {
