{"file_path":"src/modules/ai-content/adapters/api-client/DocumentProcessingApiClient.ts","overwrite":true,"initial_content":"'use client';

import { injectable } from 'tsyringe';
import { apiService, ApiError } from '@/infrastructure/api/ApiService';
import { Result } from '@/lib/utils/result';

export interface ProcessedDocumentResult {
  markdown: string;
}

const toApiError = (error: unknown): ApiError => {
  if (error instanceof ApiError) {
    return error;
  }

  return new ApiError('Unexpected document processing error', 500, error);
};

@injectable()
export class DocumentProcessingApiClient {
  async processFileApi(formData: FormData, token: string): Promise<Result<ProcessedDocumentResult, ApiError>> {
    try {
      const result = await apiService<FormData, ProcessedDocumentResult>({
        endpoint: '/api/process-file',
        method: 'POST',
        data: formData,
        token,
        isFormData: true,
      });

      return Result.ok(result);
    } catch (error: unknown) {
      return Result.fail(toApiError(error));
    }
  }

  async readFileContent(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onabort = () => reject(new Error('File reading was aborted.'));
      reader.onerror = () => reject(new Error('Failed to read file.'));
      reader.onload = () => {
        resolve(reader.result as string);
      };

      const isTextFile = file.type.startsWith('text/') || file.name.endsWith('.md');
      if (isTextFile) {
        reader.readAsText(file);
        return;
      }

      reader.readAsDataURL(file);
    });
  }
}
"}

{"file_path":"src/hooks/util/useFileUpload.ts","overwrite":true,"initial_content":"'use client';

import { useCallback, useState } from 'react';
import { useDropzone } from 'react-dropzone';
import { useAuth } from '@/context/AuthContext';
import { useToast } from '@/hooks/util/use-toast';
import { DocumentProcessingApiClient } from '@/modules/ai-content/adapters/api-client/DocumentProcessingApiClient';
import { UseFormSetValue } from 'react-hook-form';
import { runAuthenticatedResultCall } from '../data/authenticated-client-call';

interface UseFileUploadOptions {
  onSuccess?: (fileName: string) => void;
  onError?: (error: string) => void;
  fieldName?: string;
  acceptedFormats?: {
    [key: string]: string[];
  };
}

export function useFileUpload(
  setValue: UseFormSetValue<any>,
  options: UseFileUploadOptions = {},
) {
  const {
    onSuccess,
    onError,
    fieldName = 'text',
    acceptedFormats = {
      'application/pdf': ['.pdf'],
      'text/plain': ['.txt'],
      'text/markdown': ['.md'],
    },
  } = options;

  const [isUploading, setIsUploading] = useState(false);
  const { firebaseUser, refetchUser } = useAuth();
  const { toast } = useToast();

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (!file) return;

    if (!firebaseUser) {
      const errorMsg = 'You must be logged in to process files.';
      toast({
        title: 'Authentication Error',
        description: errorMsg,
        variant: 'destructive',
      });
      onError?.(errorMsg);
      return;
    }

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);

    try {
      const result = await runAuthenticatedResultCall(firebaseUser, DocumentProcessingApiClient, (client, token) =>
        client.processFileApi(formData, token),
      );

      setValue(fieldName, result.markdown, { shouldValidate: true });

      const successMsg = `Text extracted from ${file.name}.`;
      toast({ title: 'File Processed', description: successMsg });

      onSuccess?.(file.name);
      refetchUser();
    } catch (error: unknown) {
      const errorMsg = error instanceof Error ? error.message : 'Failed to process file';
      toast({
        title: 'File Processing Failed',
        description: errorMsg,
        variant: 'destructive',
      });
      onError?.(errorMsg);
    } finally {
      setIsUploading(false);
    }
  }, [fieldName, firebaseUser, onError, onSuccess, refetchUser, setValue, toast]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    multiple: false,
    accept: acceptedFormats,
  });

  return {
    isUploading,
    getRootProps,
    getInputProps,
    isDragActive,
  };
}
"}

