{"file_path":"src/hooks/auth/use-auth-mutations.ts","overwrite":true,"initial_content":"'use client';

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useRouter } from 'next/navigation';
import { AuthApiClient } from '@/modules/users/adapters/api-client/AuthApiClient';
import { container } from '@/infrastructure/di/container';
import { UserApiClient } from '@/modules/users/adapters/api-client/UserApiClient';
import { useToast } from '@/hooks/util/use-toast';
import { handleErrorUtility } from '@/lib/utils/errorUtils';
import { useAuth } from '@/context/AuthContext';
import { userKeys } from '@/lib/query-keys';
import { getAuth, signInWithPhoneNumber, type ConfirmationResult, type User as FirebaseUser } from 'firebase/auth';
import { initializeFirebase } from '@/firebase';
import { useState } from 'react';
import { LoginCredentials } from '@/lib/utils/authUtils';
import { UserProfile } from '@/modules/users/domain/entities/User';
import { SignupCredentials } from '@/components/auth/SignupForm';
import { runAuthenticatedResultCall } from '../data/authenticated-client-call';

const { firebaseApp: app } = initializeFirebase();

export function useLogin() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { toast } = useToast();

  return useMutation({
    mutationFn: async (credentials: LoginCredentials) => {
      const result = await container.resolve(AuthApiClient).loginWithEmail(credentials);
      if (result.isFailure) throw result.error;
      return result.getValue();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: userKeys.all() });
      router.push('/builder');
      toast({ title: 'Welcome back!' });
    },
    onError: (error) => handleErrorUtility(error, 'Login Failed'),
  });
}

async function handleFirstSignIn(user: FirebaseUser) {
  try {
    const existingProfile = await runAuthenticatedResultCall(user, UserApiClient, (client, token) =>
      client.fetchUserProfile(user.uid, token),
    );

    if (!existingProfile) {
      const profileData: Partial<UserProfile> = {
        id: user.uid,
        name: user.displayName || `User ${user.uid.slice(0, 6)}`,
        email: user.email || '',
      };

      const result = await container.resolve(AuthApiClient).createOrUpdateUserProfileApi(
        user.uid,
        profileData,
        await user.getIdToken(),
      );
      if (result.isFailure) {
        throw result.error;
      }
    }
  } catch (error) {
    console.error('Error during first sign-in profile check:', error);
  }
}

export function useGoogleSignIn() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { toast } = useToast();

  return useMutation({
    mutationFn: async () => {
      const result = await container.resolve(AuthApiClient).loginWithGoogle();
      if (result.isFailure) throw result.error;
      return result.getValue();
    },
    onSuccess: async (userCredential) => {
      if (userCredential.isNewUser) {
        await handleFirstSignIn(userCredential.user);
      }
      queryClient.invalidateQueries({ queryKey: userKeys.all() });
      router.push('/builder');
      toast({ title: `Welcome, ${userCredential.user.displayName}!` });
    },
    onError: (error) => handleErrorUtility(error, 'Google Sign-In Failed'),
  });
}

export function usePhoneSignIn() {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const router = useRouter();
  const queryClient = useQueryClient();
  const { toast } = useToast();

  const sendOtp = async (phoneNumber: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const auth = getAuth(app);
      const confirmationResult = await signInWithPhoneNumber(auth, phoneNumber, (window as any).recaptchaVerifier);
      return confirmationResult;
    } catch (err: any) {
      setError(err.message);
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  const verifyOtp = async (confirmationResult: ConfirmationResult, otp: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const userCredential = await confirmationResult.confirm(otp);
      const { getAdditionalUserInfo } = await import('firebase/auth');
      const info = getAdditionalUserInfo(userCredential);
      if (info?.isNewUser) {
        await handleFirstSignIn(userCredential.user);
      }
      queryClient.invalidateQueries({ queryKey: userKeys.all() });
      router.push('/builder');
      toast({ title: 'Welcome!' });
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  return { sendOtp, verifyOtp, isLoading, error };
}

export function useLogout() {
  const router = useRouter();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const result = await container.resolve(AuthApiClient).serviceLogoutUser();
      if (result.isFailure) throw result.error;
      return result.getValue();
    },
    onSuccess: () => {
      queryClient.clear();
      router.push('/login');
    },
    onError: (error) => handleErrorUtility(error, 'Logout Failed'),
  });
}

export function useSignup(options?: { onSuccess?: (data: any) => void }) {
  const router = useRouter();
  const { toast } = useToast();

  return useMutation({
    mutationFn: async (credentials: SignupCredentials) => {
      const client = container.resolve(AuthApiClient);
      const result = await client.serviceSignupUser(credentials);
      if (result.isFailure) throw result.error;
      return result.getValue();
    },
    onSuccess: (data) => {
      toast({
        title: 'Account Created',
        description: 'Your account has been successfully created. Please log in.',
      });
      router.push('/login');
      options?.onSuccess?.(data);
    },
    onError: (error) => {
      handleErrorUtility(error, 'Signup Failed');
    },
  });
}

export function useForgotPassword() {
  const { toast } = useToast();
  const router = useRouter();
  return useMutation({
    mutationFn: (email: string) => container.resolve(AuthApiClient).forgotPasswordService(email),
    onSuccess: () => {
      toast({
        title: 'Password Reset Email Sent',
        description: 'Please check your inbox for instructions to reset your password.',
      });
      router.push('/login');
    },
    onError: (error) => handleErrorUtility(error, 'Password Reset Failed'),
  });
}

export function useForgotPasswordLoggedIn() {
  const { firebaseUser } = useAuth();
  const { toast } = useToast();
  return useMutation({
    mutationFn: async () => {
      if (!firebaseUser?.email) {
        throw new Error('No authenticated user email found.');
      }
      return container.resolve(AuthApiClient).forgotPasswordService(firebaseUser.email);
    },
    onSuccess: () => {
      toast({
        title: 'Password Reset Email Sent',
        description: 'Please check your inbox for instructions to reset your password.',
      });
    },
    onError: (error) => handleErrorUtility(error, 'Failed to send reset email'),
  });
}

export function useSendPasswordReset() {
  const { firebaseUser } = useAuth();
  const { toast } = useToast();
  return useMutation({
    mutationFn: async (userId: string) =>
      runAuthenticatedResultCall(firebaseUser, AuthApiClient, (client, token) =>
        client.sendPasswordResetEmailApi(userId, token),
      ),
    onSuccess: (data) => {
      toast({
        title: 'Success',
        description: data.message || 'Password reset email sent successfully.',
      });
    },
    onError: (error) => {
      handleErrorUtility(error, 'Failed to Send Email');
    },
  });
}
"}

{"file_path":"src/components/api-docs/ApiTester.tsx","overwrite":true,"initial_content":"'use client';

import { useState } from 'react';
import { useTheme } from 'next-themes';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Send, Loader2, ServerCrash } from 'lucide-react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { type ApiEndpoint } from '@/config/api-docs';
import dynamic from 'next/dynamic';
import { useAuth } from '@/context/AuthContext';
import { useToast } from '@/hooks';
import { apiService } from '@/infrastructure/api/ApiService';

const ReactJson = dynamic(() => import('@microlink/react-json-view'), { ssr: false });

interface ApiTesterProps {
  endpoint: ApiEndpoint;
}

export function ApiTester({ endpoint }: ApiTesterProps) {
  const { firebaseUser } = useAuth();
  const { toast } = useToast();
  const { resolvedTheme } = useTheme();
  const [body, setBody] = useState(endpoint.requestBody ? JSON.stringify(endpoint.requestBody, null, 2) : '');
  const [response, setResponse] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSendRequest = async () => {
    setIsLoading(true);
    setError(null);
    setResponse(null);

    try {
      if (endpoint.auth !== 'public' && !firebaseUser) {
        throw new Error('Authentication required for this endpoint.');
      }

      const parsedBody = endpoint.method !== 'GET' && body ? JSON.parse(body) : undefined;
      const data = await apiService<any, any>({
        endpoint: endpoint.path,
        method: endpoint.method,
        firebaseUser: endpoint.auth !== 'public' ? firebaseUser : undefined,
        data: parsedBody,
      });

      setResponse(data);
    } catch (err: any) {
      const errorMessage = err instanceof Error ? err.message : 'Request failed';
      setError(errorMessage);
      toast({
        title: 'API Request Failed',
        description: errorMessage,
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="border rounded-lg p-4 space-y-4 bg-muted/30">
      <h4 className="font-semibold text-sm flex items-center gap-2">
        <Send className="w-4 h-4" />
        Live API Tester
      </h4>

      {endpoint.method !== 'GET' && (
        <div className="space-y-2">
          <Label htmlFor="api-tester-body">Request Body</Label>
          <Textarea
            id="api-tester-body"
            value={body}
            onChange={(e) => setBody(e.target.value)}
            rows={5}
            className="font-mono text-xs"
            placeholder="Enter JSON request body..."
            disabled={isLoading}
          />
        </div>
      )}

      <Button onClick={handleSendRequest} disabled={isLoading} className="w-full">
        {isLoading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Send className="mr-2 h-4 w-4" />}
        Send Request
      </Button>

      {(response || error) && (
        <div className="space-y-2 pt-4 border-t">
          <Label>Response</Label>
          <ScrollArea className="h-64 rounded-md border p-2 bg-background">
            {error ? (
              <div className="p-4 text-center text-destructive">
                <ServerCrash className="mx-auto h-8 w-8 mb-2" />
                <p>{error}</p>
              </div>
            ) : (
              <ReactJson
                src={response}
                theme={resolvedTheme === 'dark' ? 'monokai' : 'rjv-default'}
                collapsed={false}
                displayDataTypes={false}
                name={false}
                style={{ background: 'transparent' }}
              />
            )}
          </ScrollArea>
        </div>
      )}
    </div>
  );
}
"}

{"file_path":"src/components/agent/AgentPlayground.tsx","overwrite":true,"initial_content":"'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { CornerDownLeft, Loader2, Wand2 } from 'lucide-react';
import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';

import { runAgentFlow } from '@/ai/flows/run-agent-flow';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { Form, FormControl, FormField, FormItem } from '@/components/ui/form';
import { Textarea } from '@/components/ui/textarea';
import { useAgentManager } from '@/hooks/use-agent-store';
import type { AgentProperties } from '@/modules/ai/domain/entities/Agent';
import { useMutation } from '@tanstack/react-query';
import { toast } from '../ui/use-toast';
import { ResponseDisplay } from './ResponseDisplay';
import { useAuth } from '@/context/AuthContext';
import { getAuthenticatedToken } from '@/lib/utils/authUtils';

interface AgentPlaygroundProps {
  agent: AgentProperties | null;
}

const formSchema = z.object({
  userPrompt: z.string().min(1, 'Please enter a prompt.'),
});

type PlaygroundFormValues = z.infer<typeof formSchema>;

function AgentPlayground({ agent }: AgentPlaygroundProps) {
  const { responses, setResponse } = useAgentManager();
  const { firebaseUser, isGuest } = useAuth();

  const form = useForm<PlaygroundFormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      userPrompt: '',
    },
  });

  useEffect(() => {
    form.reset({ userPrompt: '' });
  }, [agent, form]);

  const mutation = useMutation({
    // @ts-expect-error - Genkit Action type vs MutationFunction type mismatch
    mutationFn: runAgentFlow,
    onSuccess: (data) => {
      if (agent) {
        setResponse(agent.id, agent.id, { response: data, prompt: form.getValues('userPrompt') });
      }
    },
    onError: (error) => {
      toast({
        title: 'Error Running Agent',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  async function onSubmit(values: PlaygroundFormValues) {
    if (!agent || !firebaseUser) return;
    const token = await getAuthenticatedToken(firebaseUser);
    const systemPrompt = `${agent.prompt}\n\n${(agent.guidelines || []).join('\n')}`;
    mutation.mutate({ systemPrompt, userPrompt: values.userPrompt, token });
  }

  if (!agent) {
    return (
      <div className="flex h-full items-center justify-center bg-muted/30">
        <div className="text-center">
          <Wand2 className="mx-auto h-12 w-12 text-muted-foreground" />
          <h2 className="mt-4 text-xl font-semibold">Select an Agent</h2>
          <p className="mt-1 text-muted-foreground">Choose an agent from the sidebar to start testing.</p>
        </div>
      </div>
    );
  }

  const agentResponses = (agent && responses[agent.id]?.[agent.id]) || [];

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-4 border-b bg-background p-4">
        <Avatar className="h-10 w-10">
          <AvatarFallback>{agent.name.charAt(0)}</AvatarFallback>
        </Avatar>
        <div>
          <h1 className="text-lg font-semibold">{agent.name}</h1>
          <p className="text-sm text-muted-foreground">{agent.description}</p>
        </div>
      </header>
      <div className="flex-1 overflow-y-auto p-4">
        {agentResponses.length > 0 ? (
          <div className="space-y-6">
            {agentResponses.map((res, index) => (
              <ResponseDisplay key={index} response={res.response} prompt={res.prompt} />
            ))}
          </div>
        ) : (
          <div className="flex h-full items-center justify-center">
            <p className="text-muted-foreground">No responses yet for this agent.</p>
          </div>
        )}
      </div>
      <div className="border-t bg-background p-4">
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="relative">
            <FormField
              control={form.control}
              name="userPrompt"
              render={({ field }) => (
                <FormItem>
                  <FormControl>
                    <Textarea
                      {...field}
                      placeholder={`Ask ${agent.name} to do something...`}
                      className="min-h-[80px] w-full resize-none pr-20"
                      disabled={mutation.isPending || isGuest}
                    />
                  </FormControl>
                </FormItem>
              )}
            />
            <Button type="submit" size="sm" className="absolute bottom-3 right-3" disabled={mutation.isPending || isGuest}>
              {mutation.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <CornerDownLeft className="mr-2 h-4 w-4" />
              )}
              Run
            </Button>
          </form>
        </Form>
      </div>
    </div>
  );
}

export default AgentPlayground;
"}

{"file_path":"src/hooks/util/useExport.ts","overwrite":true,"initial_content":"'use client';

import { useState } from 'react';
import { saveAs } from 'file-saver';
import { toast } from './use-toast';
import type { Project, ProjectContent } from '@/modules/projects/domain/entities/Project';
import { templates as docxTemplates, type DocxTemplateKey } from '@/modules/ai-content/infrastructure/exporters/DocxStyles';
import { templates as pptxTemplates, type PptxTemplateKey } from '@/modules/templates/infrastructure/PptxStyles';
import type { ConversionOptions } from '@/modules/ai-content/domain/types/export-types';
import { container } from '@/infrastructure/di/container';
import { IPptxExportServiceToken } from '@/modules/ai-content/domain/services/IExportService';
import { apiService } from '@/infrastructure/api/ApiService';

interface DocxExportParams {
  project: Project;
  options: {
    template: DocxTemplateKey;
    pageNumbers: boolean;
  };
  selectedContent: ProjectContent;
}

interface PptxExportParams {
  project: Project;
  options: {
    template: PptxTemplateKey;
    isRtl: boolean;
    includeToc: boolean;
  };
  selectedContent: ProjectContent;
}

export function useExport() {
  const [isExporting, setIsExporting] = useState(false);

  const exportReportDocx = async ({ project, options, selectedContent }: DocxExportParams) => {
    if (selectedContent.length === 0) {
      toast({ title: 'Export Canceled', description: 'No content selected to export.', variant: 'destructive' });
      return;
    }
    setIsExporting(true);
    try {
      const templateStyles = docxTemplates[options.template] || docxTemplates.modern;

      const apiOptions: Omit<ConversionOptions, 'coverPageMarkdown'> = {
        styles: templateStyles.styles,
        customStyles: templateStyles.customStyles,
        pageNumbers: options.pageNumbers,
        isRtl: false,
      };

      const selectedContentPlain = selectedContent.map((item) => item.toStateObject());
      const blob = await apiService<
        { project: ReturnType<Project['toStateObject']>; selectedContent: unknown[]; options: Omit<ConversionOptions, 'coverPageMarkdown'> },
        Blob
      >({
        endpoint: '/api/export/docx',
        method: 'POST',
        data: {
          project: project.toStateObject(),
          selectedContent: selectedContentPlain,
          options: apiOptions,
        },
        responseType: 'blob',
      });

      saveAs(blob, `${project.name.replace(/\s+/g, '_')}_report.docx`);
      toast({ title: 'Export Successful', description: 'Report exported as DOCX.' });
    } catch (error: unknown) {
      console.error('DOCX Export Error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Could not generate the DOCX file.';
      toast({
        title: 'Export Failed',
        description: errorMessage,
        variant: 'destructive',
        duration: 7000,
      });
    } finally {
      setIsExporting(false);
    }
  };

  const exportPresentationPptx = async ({ project, options, selectedContent }: PptxExportParams) => {
    if (selectedContent.length === 0) {
      toast({ title: 'Export Canceled', description: 'No content selected to export.', variant: 'destructive' });
      return;
    }

    setIsExporting(true);
    try {
      const templateStyles = pptxTemplates[options.template] || pptxTemplates.modern;
      const client = container.resolve<any>(IPptxExportServiceToken);

      const result = await client.export(project, selectedContent, {
        styles: templateStyles.styles,
        isRtl: options.isRtl,
        includeToc: options.includeToc,
      });

      const blob = result instanceof Blob
        ? result
        : new Blob([result as any], {
            type: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
          });
      saveAs(blob, `${project.name.replace(/\s+/g, '_')}_presentation.pptx`);

      toast({ title: 'Export Successful', description: 'Presentation exported as PPTX.' });
    } catch (error: unknown) {
      console.error('PPTX Export Error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Could not generate the PPTX file.';
      toast({
        title: 'Export Failed',
        description: errorMessage,
        variant: 'destructive',
        duration: 7000,
      });
    } finally {
      setIsExporting(false);
    }
  };

  return {
    isExporting,
    exportReportDocx,
    exportPresentationPptx,
  };
}
"}

{"file_path":"src/hooks/__tests__/use-agent-store.test.tsx","overwrite":true,"initial_content":"import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, renderHook, waitFor } from '@testing-library/react';

jest.mock('@/context/AuthContext', () => ({ useAuth: jest.fn() }));
jest.mock('@/hooks/data/authenticated-client-call', () => ({ runAuthenticatedClientCall: jest.fn() }));
jest.mock('@/lib/utils/cache', () => ({ getFromCache: jest.fn(), saveToCache: jest.fn() }));
jest.mock('@/hooks/util/use-toast', () => ({ toast: jest.fn() }));

const { useAuth } = jest.requireMock('@/context/AuthContext') as { useAuth: jest.Mock };
const { runAuthenticatedClientCall } = jest.requireMock('@/hooks/data/authenticated-client-call') as { runAuthenticatedClientCall: jest.Mock };
const { getFromCache, saveToCache } = jest.requireMock('@/lib/utils/cache') as { getFromCache: jest.Mock; saveToCache: jest.Mock };

const { useAgentManager } = require('../use-agent-store') as typeof import('../use-agent-store');

describe('useAgentManager', () => {
  const firebaseUser = { uid: 'agent-user-1' } as { uid: string };

  const createWrapper = (queryClient: QueryClient) => {
    const Wrapper = ({ children }: { children: React.ReactNode }) => (
      <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
    );
    Wrapper.displayName = 'AgentStoreQueryClientWrapper';
    return Wrapper;
  };

  beforeEach(() => {
    jest.clearAllMocks();
    useAuth.mockReturnValue({ firebaseUser });
    getFromCache.mockReturnValue(undefined);
  });

  it('hydrates agents through the authenticated helper and auto-selects the first agent', async () => {
    runAuthenticatedClientCall.mockResolvedValue([
      { id: 'agent-1', name: 'Agent One', prompt: 'Prompt 1', guidelines: [] },
