   6 export class ApiError extends Error {
   7   constructor(
   8     public message: string,
   9     public status: number,
  10     public details?: any
  11   ) {
  12     super(message);
  13     this.name = 'ApiError';
  14   }
  15 }
  16 
  17 interface ApiServiceOptions<T> {
  18   endpoint: string;
  19   method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  20   data?: T;
  21   token?: string; // Allow passing token directly
  22   firebaseUser?: FirebaseUser | null; // Or pass the user object
  23   headers?: Record<string, string>;
  24   isFormData?: boolean;
  25 }
  26 
  27 /**
  28  * A unified API service function to handle all client-server communication.
  29  * It automatically handles authentication, request body serialization, and response parsing.
  30  *
  31  * @param options - The configuration for the API request.
  32  * @returns A promise that resolves to the JSON response from the API.
  33  * @throws An ApiError if the request fails or the user is not authenticated when required.
  34  */
  35 export async function apiService<TRequest = any, TResponse = any>(
  36   options: ApiServiceOptions<TRequest>
  37 ): Promise<TResponse> {
  38   const {
  39     endpoint,
  40     method = 'GET',
  41     data,
  42     token: directToken,
  43     firebaseUser,
  44     headers = {},
  45     isFormData = false,
  46   } = options;
  47 
  48   let authToken = directToken;
  49 
  50   if (!authToken && firebaseUser) {
  51     authToken = await getAuthenticatedToken(firebaseUser);
  52   }
  53 
  54   const config: RequestInit = {
  55     method,
  56     headers: { ...headers },
  57   };
  58 
  59   if (authToken) {
  60     config.headers = {
  61       ...config.headers,
  62       'Authorization': `Bearer ${authToken}`,
  63     };
  64   }
  65 
  66   if (data) {
  67     if (isFormData) {
  68       // Don't set Content-Type for FormData, browser does it with boundary
  69       config.body = data as unknown as FormData;
  70     } else {
  71       (config.headers as Record<string, string>)['Content-Type'] = 'application/json';
  72       config.body = JSON.stringify(data);
  73     }
  74   }
  75 
  76   const response = await fetch(endpoint, config);
  77 
  78   if (!response.ok) {
  79     let errorData;
  80     try {
  81       errorData = await response.json();
  82     } catch {
  83       // If the response is not JSON, use the status text
  84       errorData = { message: response.statusText || 'An unknown error occurred.' };
  85     }
  86     throw new ApiError(errorData.message || response.statusText, response.status, errorData.details);
  87   }
  88 
  89   // Handle cases where the response might be empty (e.g., DELETE 204 No Content)
  90   const contentType = response.headers.get('content-type');
  91   if (contentType && contentType.includes('application/json')) {
  92     return response.json();
  93   }
  94   // Return an empty object or a success indicator for non-JSON responses
  95   return {} as TResponse;
  96 }
  97 
