  20 function formatTransactionsToMarkdown(transactions: TransactionProperties[], dateRange: DateRange): string {
  21     let markdown = `# Financial Report\n\n`;
  22     if (dateRange.from && dateRange.to) {
  23         markdown += `**Date Range:** ${format(dateRange.from, "LLL dd, y")} - ${format(dateRange.to, "LLL dd, y")}\n\n`;
  24     }
  25     
  26     markdown += `| Transaction ID | User Name | Plan | Amount | Status | Date |\n`;
  27     markdown += `|---|---|---|---|---|---|\n`;
  28 
  29     let totalVerified = 0;
  30     transactions.forEach(t => {
  31         markdown += `| ${t.id.slice(0, 8)} | ${t.userName} | ${t.planName} | $${t.price.toFixed(2)} | ${t.status} | ${new Date(t.createdAt).toLocaleDateString()} |\n`;
  32         if (t.status === 'verified') {
  33             totalVerified += t.price;
  34         }
  35     });
  36 
  37     markdown += `\n## Summary\n\n`;
  38     markdown += `- **Total Transactions:** ${transactions.length}\n`;
  39     markdown += `- **Total Verified Revenue:** $${totalVerified.toFixed(2)}\n`;
  40 
  41     return markdown;
  42 }
  43 
