  53         if (!dateRange?.from || !dateRange?.to || !firebaseUser) {
  54             toast({
  55                 title: t('adminFinancialReport.missingInfoError'),
  56                 description: t('adminFinancialReport.missingInfoDesc'),
  57                 variant: 'destructive',
  58             });
  59             return;
  60         }
  61 
  62         setIsLoading(true);
  63         try {
  64             const token = await firebaseUser.getIdToken();
  65             const client = container.resolve(TransactionApiClient);
