  39 // Helper function to convert JSON to Markdown
  40 function jsonToMarkdown(json: any, level = 1): string {
  41     if (json === null || json === undefined) return '';
  42     if (typeof json !== 'object') return String(json);
  43 
  44     let markdown = '';
  45 
  46     if (Array.isArray(json)) {
  47         json.forEach(item => {
  48             if (typeof item === 'object' && item !== null && !Array.isArray(item)) {
  49                 // For objects inside an array, create a list item and then process the object
  50                 const objectContent = Object.entries(item).map(([key, value]) => `**${key.replace(/_/g, ' ')}:** ${value}`).join('; ');
  51                 markdown += `- ${objectContent}\n`;
  52             } else {
  53                 markdown += `- ${jsonToMarkdown(item, level + 1)}\n`;
  54             }
  55         });
  56     } else {
  57         for (const key in json) {
  58             if (Object.prototype.hasOwnProperty.call(json, key)) {
  59                 const value = json[key];
  60                 // Convert camelCase or snake_case to Title Case for headings
  61                 const title = key.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ').replace(/^./, str => str.toUpperCase());
  62 
  63                 if (typeof value === 'object' && value !== null) {
  64                     markdown += `\n${'#'.repeat(level + 1)} ${title}\n\n`;
  65                     markdown += jsonToMarkdown(value, level + 1);
  66                 } else {
  67                     markdown += `**${title}:** ${String(value)}\n\n`;
  68                 }
  69             }
  70         }
  71     }
  72     return markdown;
  73 }
