    return error;
  }

  return new ApiError('Unexpected generation logs error', 500, error);
};

@injectable()
export class GenerationLogApiClient {
  async fetchGenerationLogs(params: FetchLogsParams): Promise<Result<GenerationLogsPage, ApiError>> {
