interface UserTableRowProps { user: User; }

export function UserTableRow({ user }: UserTableRowProps) {
  const { t } = useLocalization();
  const queryClient = useQueryClient();
  const { firebaseUser } = useAuth();
  const sendPasswordResetMutation = useSendPasswordReset();

  async function prefetchUser(userId: string) {
    if (!firebaseUser) return;
    await queryClient.prefetchQuery({
      queryKey: userKeys.profile(userId),
      queryFn: async () => {
        const profile = await runAuthenticatedResultCall(firebaseUser, UserApiClient, (client, token) =>
          client.fetchUserById(userId, token),
        );
        return new User(profile);
      },
      staleTime: 1000 * 60,
    });
  }

  return (
    <TableRow>
      <TableCell className="font-medium">{user.name}</TableCell>
      <TableCell>{user.email}</TableCell>
      <TableCell><Badge variant={user.role === 'admin' ? 'default' : 'secondary'}>{t(`roles.${user.role}`)}</Badge></TableCell>
      <TableCell>{user.credits}</TableCell>
      <TableCell>{user.getFormattedDate()}</TableCell>
      <TableCell className="text-right">
        <GiftCreditsDialog user={user} />
        <AlertDialog>
          <AlertDialogTrigger asChild><Button variant="ghost" size="icon"><KeyRound className="h-4 w-4" /><span className="sr-only">Reset Password</span></Button></AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader><AlertDialogTitle>Reset Password</AlertDialogTitle><AlertDialogDescription>An email will be sent to {user.email} with instructions to reset their password. Are you sure?</AlertDialogDescription></AlertDialogHeader>
            <AlertDialogFooter><AlertDialogCancel>Cancel</AlertDialogCancel><AlertDialogAction onClick={() => sendPasswordResetMutation.mutate(user.id)}>Send Reset Email</AlertDialogAction></AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
        <Button asChild variant="ghost" size="icon" onMouseEnter={() => prefetchUser(user.id)} aria-label={`${t('manageUsers.editUserSr')} ${user.name}`}>
          <Link href={`/admin/manage-users/${user.id}/edit`}><Pencil className="h-4 w-4" /></Link>
        </Button>
      </TableCell>
    </TableRow>
  );
}
"}

{"file_path":"src/components/report-mode/file-manager/AnalystAgent.tsx","overwrite":true,"initial_content":"'use client';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Textarea } from '@/components/ui/textarea';
import { useAuth } from '@/context/AuthContext';
import { useLocalization } from '@/context/LocalizationContext';
import { toast, useBuilderStore } from '@/hooks';
import { markdownComponents } from '@/lib/utils/markdown-styles';
import { zodResolver } from '@hookform/resolvers/zod';
import { useMutation } from '@tanstack/react-query';
import { Braces, BrainCircuit, Loader2, PlusCircle, Wand2 } from 'lucide-react';
import { useTheme } from 'next-themes';
import dynamic from 'next/dynamic';
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import ReactMarkdown from 'react-markdown';
import { z } from 'zod';

const ReactJson = dynamic(() => import('@microlink/react-json-view'), { ssr: false });
const analysisSchema = z.object({ prompt: z.string().min(10, 'Prompt must be at least 10 characters long.') });
type AnalysisFormValues = z.infer<typeof analysisSchema>;

function jsonToMarkdown(json: any, level = 1): string {
  if (json === null || json === undefined) return '';
  if (typeof json !== 'object') return String(json);
  let markdown = '';
  if (Array.isArray(json)) {
    json.forEach((item) => {
      if (typeof item === 'object' && item !== null && !Array.isArray(item)) {
        const objectContent = Object.entries(item).map(([key, value]) => `**${key.replace(/_/g, ' ')}:** ${value}`).join('; ');
        markdown += `- ${objectContent}\n`;
      } else {
        markdown += `- ${jsonToMarkdown(item, level + 1)}\n`;
      }
    });
  } else {
    for (const key in json) {
      if (Object.prototype.hasOwnProperty.call(json, key)) {
        const value = json[key];
        const title = key.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ').replace(/^./, (str) => str.toUpperCase());
        if (typeof value === 'object' && value !== null) {
          markdown += `\n${'#'.repeat(level + 1)} ${title}\n\n`;
          markdown += jsonToMarkdown(value, level + 1);
        } else {
          markdown += `**${title}:** ${String(value)}\n\n`;
        }
      }
    }
  }
  return markdown;
}

export default function AnalystAgent() {
  const { t } = useLocalization();
  const { project, updateProject } = useBuilderStore();
  const externalContext = project?.externalContext || [];
  const { firebaseUser, refetchUser, isGuest } = useAuth();
  const { resolvedTheme } = useTheme();
  const [markdownResult, setMarkdownResult] = useState<string | null>(null);

  const form = useForm<AnalysisFormValues>({ resolver: zodResolver(analysisSchema), defaultValues: { prompt: '' } });

  const analysisMutation = useMutation({
    mutationFn: async (_variables: { prompt: string; contextFiles: any[] }) => {
      const testData = {
        schema: 'z.object({ project_name: z.string(), stakeholders: z.array(z.object({ name: z.string(), role: z.string() })), summary: z.string() })',
        data: {
          project_name: 'AI-Powered Writing Platform',
          stakeholders: [
            { name: 'Academic Users', role: 'Primary users for research and writing.' },
            { name: 'Business Professionals', role: 'Secondary users for report generation.' },
            { name: 'Development Team', role: 'Internal team responsible for building the platform.' },
          ],
          summary: 'The project aims to build a comprehensive AI platform called Arkan to assist academics and professionals in writing and document generation, featuring a modular architecture with 23+ AI tools.',
        },
      };
      await new Promise((resolve) => setTimeout(resolve, 1000));
      return testData;
    },
    onSuccess: (data) => {
      refetchUser();
      toast({ title: t('builder.files.toasts.analysisComplete'), description: t('builder.files.toasts.analysisCompleteDesc') });
      setMarkdownResult(jsonToMarkdown(data.data));
    },
    onError: (error: Error) => {
      toast({ title: t('builder.files.toasts.analysisFailed'), description: error.message, variant: 'destructive' });
    },
  });

  async function onSubmit(data: AnalysisFormValues) {
    if (externalContext.length === 0) {
      toast({ title: t('builder.files.toasts.contextRequired'), description: t('builder.files.toasts.contextRequiredDesc'), variant: 'destructive' });
      return;
    }
    if (!firebaseUser) return;
    setMarkdownResult(null);
    analysisMutation.mutate({ prompt: data.prompt, contextFiles: [...externalContext] });
  }

  function handleSaveAnalysis() {
    if (!markdownResult || !form.getValues('prompt')) return;
    const fileName = form.getValues('prompt').toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '').slice(0, 50) + '.md';
    updateProject((p) => { p.addExternalContext({ fileName, content: markdownResult, type: 'context' }); });
    toast({ title: t('builder.files.toasts.analysisSaved'), description: t('builder.files.toasts.analysisSavedDesc').replace('{fileName}', fileName) });
  }

  const isProcessing = analysisMutation.isPending;
  const canAnalyze = !isGuest && !isProcessing && (firebaseUser?.uid ? project?.meta?.author === firebaseUser.uid : false);

  return (
    <Card className="h-full flex flex-col">
      <CardHeader><CardTitle className="flex items-center gap-2"><BrainCircuit className="h-5 w-5 text-primary" /> {t('builder.files.analystAgentTitle')}</CardTitle><CardDescription>{t('builder.files.analystAgentDesc')}</CardDescription></CardHeader>
      <Form {...form}><form onSubmit={form.handleSubmit(onSubmit)} className="flex-grow flex flex-col min-h-0">
        <CardContent className="space-y-4 flex-grow flex flex-col min-h-0">
          <FormField control={form.control} name="prompt" render={({ field }) => <FormItem><FormLabel>{t('builder.files.analystAgentPromptLabel')}</FormLabel><FormControl><Textarea placeholder={t('builder.files.analystAgentPromptPlaceholder')} {...field} rows={4} disabled={isProcessing || isGuest} /></FormControl><FormMessage /></FormItem>} />
          <Button type="submit" disabled={!canAnalyze || isGuest}>{isProcessing ? <Loader2 className="me-2 h-4 w-4 animate-spin" /> : <Wand2 className="me-2 h-4 w-4" />}{t('builder.files.analystAgentRunButton', { creditCost: 0 })}</Button>
          {(isProcessing || markdownResult) && <div className="space-y-2 pt-4 border-t flex-grow flex flex-col min-h-0"><div className="flex justify-between items-center"><h4 className="font-semibold text-sm">{t('builder.files.generatedReportTitle')}</h4>{analysisMutation.data && <Dialog><DialogTrigger asChild><Button variant="ghost" size="sm"><Braces className="me-2 h-4 w-4" /> {t('builder.files.viewJsonButton')}</Button></DialogTrigger><DialogContent className="max-w-3xl"><DialogHeader><DialogTitle>{t('builder.files.jsonOutputTitle')}</DialogTitle></DialogHeader><ScrollArea className="max-h-[70vh] border rounded-md bg-muted text-xs p-2"><ReactJson src={analysisMutation.data.data} theme={resolvedTheme === 'dark' ? 'monokai' : 'rjv-default'} collapsed={false} displayDataTypes={false} name={false} /></ScrollArea></DialogContent></Dialog>}</div><ScrollArea className="flex-grow border rounded-md bg-muted/50 p-4"><div className="prose dark:prose-invert max-w-none prose-sm">{isProcessing ? <div className="flex items-center justify-center h-full"><Loader2 className="h-6 w-6 animate-spin text-primary" /></div> : markdownResult ? <ReactMarkdown components={markdownComponents}>{markdownResult}</ReactMarkdown> : <p className="text-muted-foreground text-center py-10">{t('builder.files.reportPlaceholder')}</p>}</div></ScrollArea></div>}
        </CardContent>
        {markdownResult && !isProcessing && <CardFooter><Button variant="secondary" onClick={handleSaveAnalysis} disabled={!markdownResult}><PlusCircle className="me-2 h-4 w-4" />{t('builder.files.saveResultButton')}</Button></CardFooter>}
      </form></Form>
    </Card>
  );
}
"}

{"file_path":"src/app/writing-tools/lecture-generator/page.tsx","overwrite":true,"initial_content":"'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { type CreateLectureUnitOutput, type CreateLectureUnitInput } from '@/ai/schemas/lecture-generator';
import { useToast } from '@/hooks';
import { useAuth } from '@/context/AuthContext';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { SessionPlanDisplay } from '@/components/writing-tools/SessionPlanDisplay';
import { markdownComponents } from '@/lib/utils/markdown-styles';
import { apiService } from '@/infrastructure/api/ApiService';

const MarkdownPreview = ({ content }: { content: string }) => <div className="prose dark:prose-invert prose-sm max-w-none p-4 bg-muted rounded-md"><ReactMarkdown remarkPlugins={[remarkGfm]} components={markdownComponents}>{content}</ReactMarkdown></div>;

export default function LectureGeneratorPage() {
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<CreateLectureUnitOutput | null>(null);
  const [formData, setFormData] = useState<Omit<CreateLectureUnitInput, 'subTopics'>>({ lectureTopic: '', professorNotes: '', sessionDuration: 90, numActivities: 3, targetAudience: 'University-level students' });
  const [subTopicsStr, setSubTopicsStr] = useState('');
  const { toast } = useToast();
  const { firebaseUser: user } = useAuth();

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: name === 'sessionDuration' || name === 'numActivities' ? parseInt(value, 10) : value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setResult(null);

    if (!user) {
      toast({ variant: 'destructive', title: 'Authentication Error', description: 'You must be logged in to generate a lecture.' });
      setIsLoading(false);
      return;
    }

    const subTopics = subTopicsStr.split('\n').filter((topic) => topic.trim() !== '');
    if (!formData.lectureTopic || subTopics.length === 0) {
      toast({ variant: 'destructive', title: 'Missing Information', description: 'Please provide a lecture topic and at least one sub-topic.' });
      setIsLoading(false);
      return;
    }

    const input: CreateLectureUnitInput = { ...formData, subTopics };

    try {
      const data = await apiService<CreateLectureUnitInput, CreateLectureUnitOutput>({ endpoint: '/api/actions/create-lecture-unit', method: 'POST', firebaseUser: user, data: input });
      setResult(data);
      toast({ title: 'Generation Successful', description: 'Your lecture and practical session have been created.' });
    } catch (error) {
      console.error(error);
      toast({ variant: 'destructive', title: 'Generation Failed', description: error instanceof Error ? error.message : 'An unknown error occurred.' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="container mx-auto p-4 md:p-8">
      <h1 className="text-3xl font-bold mb-2">Lecture Generator</h1>
      <p className="text-muted-foreground mb-6">Design a complete lecture unit, from theory to practice.</p>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <Card><CardHeader><CardTitle>Lecture Details</CardTitle><CardDescription>Provide the core information for your lecture.</CardDescription></CardHeader><CardContent><form onSubmit={handleSubmit} className="space-y-6"><div className="space-y-2"><Label htmlFor="lectureTopic">Lecture Topic</Label><Input id="lectureTopic" name="lectureTopic" placeholder="e.g., Introduction to Quantum Computing" value={formData.lectureTopic} onChange={handleInputChange} required /></div><div className="space-y-2"><Label htmlFor="subTopics">Table of Contents (one per line)</Label><Textarea id="subTopics" name="subTopics" placeholder="e.g., What is a Qubit?\nSuperposition\nEntanglement" value={subTopicsStr} onChange={(e) => setSubTopicsStr(e.target.value)} required rows={5} /></div><div className="space-y-2"><Label htmlFor="professorNotes">Professor's Notes (Optional)</Label><Textarea id="professorNotes" name="professorNotes" placeholder="Paste your raw notes, key points, or existing materials here. The AI will structure and expand on them." value={formData.professorNotes || ''} onChange={handleInputChange} rows={8} /></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label htmlFor="sessionDuration">Practical Session Duration (minutes)</Label><Input id="sessionDuration" name="sessionDuration" type="number" value={formData.sessionDuration} onChange={handleInputChange} required /></div><div className="space-y-2"><Label htmlFor="numActivities">Number of Practical Activities</Label><Input id="numActivities" name="numActivities" type="number" value={formData.numActivities} onChange={handleInputChange} required /></div></div><Button type="submit" disabled={isLoading} className="w-full">{isLoading ? 'Generating...' : 'Generate Lecture Unit (5 Credits)'}</Button></form></CardContent></Card>
        <div className="space-y-8">{isLoading && <Card><CardContent className="p-6 flex flex-col items-center justify-center h-64"><p>Generating your lecture... please wait.</p></CardContent></Card>}{result && <><Card><CardHeader><CardTitle>Generated Theoretical Lecture</CardTitle></CardHeader><CardContent><MarkdownPreview content={result.theoreticalLecture.lectureContent} /></CardContent></Card><SessionPlanDisplay data={result.practicalSession} /></>}</div>
      </div>
    </div>
  );
}
"}

{"file_path":"src/app/profile/ApiTokenView.tsx","overwrite":true,"initial_content":"'use client';

import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { useToast } from '@/hooks';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { AlertTriangle, Check, Copy } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { getAuthenticatedToken } from '@/lib/utils/authUtils';

export function ApiTokenView() {
  const { firebaseUser } = useAuth();
  const [token, setToken] = useState<string | null>(null);
  const [isCopied, setIsCopied] = useState(false);
  const { toast } = useToast();

  const handleShowToken = async () => {
    if (firebaseUser) {
      const idToken = await getAuthenticatedToken(firebaseUser);
      setToken(idToken);
    }
  };

  const handleCopy = () => {
    if (!token) return;
    navigator.clipboard.writeText(token);
    setIsCopied(true);
    toast({ title: 'Token Copied!' });
    setTimeout(() => setIsCopied(false), 2000);
  };

  return (
    <Card>
      <CardHeader><CardTitle>API Access Token</CardTitle><CardDescription>Use this token to authenticate with the Arkan API for external integrations.</CardDescription></CardHeader>
      <CardContent className="space-y-4">
        <Alert variant="destructive"><AlertTriangle className="h-4 w-4" /><AlertDescription><strong>Warning:</strong> Treat this token like a password. Do not share it or expose it in client-side code.</AlertDescription></Alert>
        {token ? <div className="flex items-center gap-2"><Input readOnly value={token} className="font-mono text-xs" /><Button variant="outline" size="icon" onClick={handleCopy}>{isCopied ? <Check className="h-4 w-4 text-green-500" /> : <Copy className="h-4 w-4" />}</Button></div> : <p className="text-sm text-muted-foreground">Click the button to reveal your access token.</p>}
      </CardContent>
      <CardFooter><Button onClick={handleShowToken}>{token ? 'Refresh Token' : 'Show Token'}</Button></CardFooter>
    </Card>
  );
}
"}

{"file_path":"src/hooks/rag/__tests__/use-rag-hooks.test.tsx","overwrite":true,"initial_content":"import { act, renderHook, waitFor } from '@testing-library/react';

jest.mock('@/context/AuthContext', () => ({ useAuth: jest.fn() }));
jest.mock('@/infrastructure/api/ApiService', () => ({ apiService: jest.fn() }));

const { useAuth } = jest.requireMock('@/context/AuthContext') as { useAuth: jest.Mock };
const { apiService } = jest.requireMock('@/infrastructure/api/ApiService') as { apiService: jest.Mock };

const { useRAGRetrieval } = require('../use-rag-retrieval') as typeof import('../use-rag-retrieval');
const { useRAGIndexing } = require('../use-rag-indexing') as typeof import('../use-rag-indexing');

describe('RAG hooks', () => {
  const firebaseUser = { uid: 'rag-user-1' } as { uid: string };

  beforeEach(() => {
    jest.clearAllMocks();
    useAuth.mockReturnValue({ firebaseUser });
  });

  it('retrieves context through apiService and stores sources', async () => {
    apiService.mockResolvedValue({ context: 'Retrieved context', sources: [{ content: 'source', score: 0.9, type: 'reference' }] });
    const { result } = renderHook(() => useRAGRetrieval());

    await act(async () => {
      await result.current.retrieveContext('query');
    });

    await waitFor(() => expect(result.current.context).toBe('Retrieved context'));
    expect(apiService).toHaveBeenCalledWith(expect.objectContaining({ endpoint: '/api/rag/retrieve-context', method: 'POST', firebaseUser }));
    expect(result.current.sources).toHaveLength(1);
  });

  it('indexes a document through apiService and records created chunks', async () => {
    apiService.mockResolvedValue({ chunksCreated: 3 });
    const { result } = renderHook(() => useRAGIndexing());

    await act(async () => {
      await result.current.indexDocument('content', 'file.txt');
    });

    await waitFor(() => expect(result.current.success).toBe(true));
    expect(apiService).toHaveBeenCalledWith(expect.objectContaining({ endpoint: '/api/rag/index-document', method: 'POST', firebaseUser }));
    expect(result.current.chunksCreated).toBe(3);
  });
});
"}

