   3 import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
   4 import { sectionKeys } from '@/lib/query-keys';
   5 import { SectionApiClient } from '@/modules/ai-content/adapters/api-client/SectionApiClient';
   6 import { toast } from '@/hooks/util/use-toast';
   7 import { useAuth } from '@/context/AuthContext';
   8 import { Section, type SectionProperties } from '@/lib/types';
   9 import { runAuthenticatedClientCall } from './authenticated-client-call';
  10 
  11 export function useSections() {
  12   const { firebaseUser } = useAuth();
  13 
  14   return useQuery({
  15     queryKey: sectionKeys.lists(),
  16     queryFn: async () => {
  17       const sectionsData = await runAuthenticatedClientCall(firebaseUser, SectionApiClient, (client, token) =>
  18         client.fetchSections(token),
  19       );
  20 
  21       return sectionsData.map((section) => new Section(section));
  22     },
  23     enabled: Boolean(firebaseUser),
  24   });
  25 }
  26 
  27 export function useCreateSection() {
  28   const queryClient = useQueryClient();
  29   const { firebaseUser } = useAuth();
  30 
  31   return useMutation({
  32     mutationFn: async (data: Omit<SectionProperties, 'id'> & { id: string }) =>
  33       runAuthenticatedClientCall(firebaseUser, SectionApiClient, (client, token) =>
  34         client.createSection(data, token),
  35       ),
  36     onSuccess: () => {
  37       toast({ title: 'Section Created', description: 'The new section has been successfully added.' });
  38       queryClient.invalidateQueries({ queryKey: sectionKeys.lists() });
  39     },
  40     onError: (error: unknown) => {
  41       const description = error instanceof Error ? error.message : 'Could not create section.';
  42       toast({ title: 'Creation Failed', description, variant: 'destructive' });
  43     },
  44   });
  45 }
  46 
