  51   return useMutation({
  52     mutationFn: async ({ sectionId, data }: { sectionId: string; data: Partial<SectionProperties> }) =>
  53       runAuthenticatedClientCall(firebaseUser, SectionApiClient, (client, token) =>
  54         client.updateSection(sectionId, data, token),
  55       ),
  56     onSuccess: (data) => {
  57       toast({ title: 'Section Updated', description: `Section "${data.title}" has been updated.` });
  58       queryClient.invalidateQueries({ queryKey: sectionKeys.lists() });
