  60         queryClient.invalidateQueries({ queryKey: sectionKeys.detail(data.id) });
  61       }
  62     },
  63     onError: (error: unknown) => {
  64       const description = error instanceof Error ? error.message : 'Could not update section.';
  65       toast({ title: 'Update Failed', description, variant: 'destructive' });
  66     },
  67   });
  68 }
  69 
