  76       runAuthenticatedClientCall(firebaseUser, SectionApiClient, (client, token) =>
  77         client.deleteSection(sectionId, token),
  78       ),
  79     onSuccess: () => {
  80       toast({ title: 'Section Deleted', description: 'The section has been removed.' });
  81       queryClient.invalidateQueries({ queryKey: sectionKeys.lists() });
