   9 import { getMessaging, getToken, onMessage } from 'firebase/messaging';
  10 import { useEffect, useState } from 'react';
  11 
  12 export default function FirebaseMessagingProvider({ children }: { children: React.ReactNode }) {
  13     const { firebaseUser } = useAuth();
  14     const { toast } = useToast();
  15     const [, setToken] = useState<string | null>(null);
  16 
  17     useEffect(() => {
  18         if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
  19             const messaging = getMessaging(app);
  20 
  21             async function requestPermission() {
  22                 try {
  23                     const permission = await Notification.requestPermission();
  24                     if (permission === 'granted' && firebaseUser) {
  25                         const currentToken = await getToken(messaging, { vapidKey: process.env.NEXT_PUBLIC_FIREBASE_VAPID_KEY });
  26                         if (currentToken) {
  27                             setToken(currentToken);
  28                             const client = container.resolve(DeviceTokenApiClient);
  29                             await client.saveDeviceToken(firebaseUser.uid, currentToken);
  30                         } else {
  31                             console.log('No registration token available. Request permission to generate one.');
  32                         }
  33                     } else {
  34                         console.log('Unable to get permission to notify.');
  35                     }
  36                 } catch (err) {
  37                     console.error('An error occurred while retrieving token. ', err);
  38                 }
  39             }
  40 
  41             requestPermission();
  42 
  43             const unsubscribe = onMessage(messaging, (payload) => {
  44                 console.log('Message received. ', payload);
  45                 toast({
  46                     title: payload.notification?.title,
  47                     description: payload.notification?.body,
  48                 });
  49             });
  50 
  51             return () => {
  52                 unsubscribe();
  53             };
  54         }
  55     }, [firebaseUser, toast]);
  56 
