  if (error) return <Alert variant="destructive"><XCircle className="h-4 w-4" /><AlertDescription>Error loading health status: {error}</AlertDescription><Button onClick={fetchHealth} variant="outline" size="sm" className="mt-2">Retry</Button></Alert>;

  return <div className="space-y-4"><div className="flex items-center justify-between"><div><h2 className="text-2xl font-bold">RAG Health Monitor</h2><p className="text-sm text-muted-foreground">Monitor the status of your RAG system components</p></div><div className="flex items-center gap-2"><Button onClick={fetchHealth} disabled={loading} size="sm" variant="outline"><RefreshCw className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />Refresh</Button><Button onClick={() => setAutoRefresh(!autoRefresh)} size="sm" variant={autoRefresh ? 'default' : 'outline'}>{autoRefresh ? 'Disable' : 'Enable'} Auto-refresh</Button></div></div>{health && <><Card><CardHeader><div className="flex items-center justify-between"><div className="flex items-center gap-2">{getStatusIcon(health.status)}<CardTitle>Overall Status</CardTitle></div>{getStatusBadge(health.status)}</div><CardDescription>Last updated: {new Date(health.timestamp).toLocaleString()}</CardDescription></CardHeader><CardContent><div className="grid grid-cols-3 gap-4 text-sm"><div><div className="font-medium text-muted-foreground">Provider</div><div className="font-mono">{health.config.provider}</div></div><div><div className="font-medium text-muted-foreground">Embedding Model</div><div className="font-mono">{health.config.embeddingModel}</div></div><div><div className="font-medium text-muted-foreground">Vector Dimension</div><div className="font-mono">{health.config.vectorDimension}</div></div></div></CardContent></Card><Card><CardHeader><div className="flex items-center justify-between"><div className="flex items-center gap-2">{getStatusIcon(health.checks.config.status)}<CardTitle>Configuration</CardTitle></div>{getStatusBadge(health.checks.config.status)}</div></CardHeader><CardContent>{health.checks.config.details.errors?.length > 0 && <Alert variant="destructive"><AlertDescription><ul className="list-disc list-inside space-y-1">{health.checks.config.details.errors.map((err: string, idx: number) => <li key={idx}>{err}</li>)}</ul></AlertDescription></Alert>}</CardContent></Card><Card><CardHeader><div className="flex items-center justify-between"><div className="flex items-center gap-2">{getStatusIcon(health.checks.vectorStore.status)}<CardTitle>Vector Store</CardTitle></div>{getStatusBadge(health.checks.vectorStore.status)}</div></CardHeader><CardContent><div className="space-y-2 text-sm">{health.checks.vectorStore.details.type && <div><span className="font-medium">Type:</span> <span className="font-mono">{health.checks.vectorStore.details.type}</span></div>}{health.checks.vectorStore.details.url && <div><span className="font-medium">URL:</span> <span className="font-mono">{health.checks.vectorStore.details.url}</span></div>}{health.checks.vectorStore.details.collection && <div><span className="font-medium">Collection:</span> <span className="font-mono">{health.checks.vectorStore.details.collection}</span></div>}{health.checks.vectorStore.details.totalChunks !== undefined && <div><span className="font-medium">Total Chunks:</span> <span className="font-mono">{health.checks.vectorStore.details.totalChunks.toLocaleString()}</span></div>}{health.checks.vectorStore.details.error && <Alert variant="destructive"><AlertDescription>{health.checks.vectorStore.details.error}</AlertDescription></Alert>}</div></CardContent></Card><Card><CardHeader><div className="flex items-center justify-between"><div className="flex items-center gap-2">{getStatusIcon(health.checks.ollama.status)}<CardTitle>Ollama Embedding Service</CardTitle></div>{getStatusBadge(health.checks.ollama.status)}</div></CardHeader><CardContent><div className="space-y-2 text-sm">{health.checks.ollama.details.url && <div><span className="font-medium">URL:</span> <span className="font-mono">{health.checks.ollama.details.url}</span></div>}{health.checks.ollama.details.model && <div><span className="font-medium">Model:</span> <span className="font-mono">{health.checks.ollama.details.model}</span></div>}{health.checks.ollama.details.modelAvailable !== undefined && <div><span className="font-medium">Model Available:</span> <span className="font-mono">{health.checks.ollama.details.modelAvailable ? 'Yes' : 'No'}</span></div>}{health.checks.ollama.details.error && <Alert variant="destructive"><AlertDescription>{health.checks.ollama.details.error}</AlertDescription></Alert>}</div></CardContent></Card></>}</div>;
}
