import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { useGoogleSignIn, useLogin } from '@/hooks/auth/use-auth-mutations';
import { zodResolver } from '@hookform/resolvers/zod';
import { AlertCircle, Loader2, Phone } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { handleErrorUtility } from '@/lib/utils/errorUtils';
import { LoginCredentials } from '@/lib/utils/authUtils';
import { apiService } from '@/infrastructure/api/ApiService';

const formSchema = z.object({ email: z.string().email({ message: 'Please enter a valid email address.' }), password: z.string().min(1, { message: 'Password is required.' }) });

export default function LoginForm() {
  const router = useRouter();
  const loginMutation = useLogin();
  const googleSignInMutation = useGoogleSignIn();
  const form = useForm<LoginCredentials>({ resolver: zodResolver(formSchema), defaultValues: { email: '', password: '' } });

  useEffect(() => { const errorData = loginMutation.error as any; if (errorData?.message) { form.setError('root.serverError', { type: 'manual', message: errorData.message }); } }, [loginMutation.error, form]);
  function onSubmit(values: LoginCredentials) { form.clearErrors('root.serverError'); loginMutation.mutate(values); }
  const handleGuestLogin = async () => { try { await apiService<undefined, unknown>({ endpoint: '/api/auth/guest', method: 'POST' }); router.push('/builder'); } catch (error) { handleErrorUtility(error, 'Guest Login Failed'); } };
  const isPending = loginMutation.isPending || googleSignInMutation.isPending;
  const formLevelError = form.formState.errors.root?.serverError;

  return <Form {...form}><form onSubmit={form.handleSubmit(onSubmit)} className="grid gap-4">{formLevelError && <Alert variant="destructive"><AlertCircle className="h-4 w-4" /><AlertTitle>Login Error</AlertTitle><AlertDescription>{formLevelError.message}</AlertDescription></Alert>}<FormField control={form.control} name="email" render={({ field }) => <FormItem><FormLabel>Email</FormLabel><FormControl><Input placeholder="name@example.com" {...field} disabled={isPending} /></FormControl><FormMessage /></FormItem>} /><FormField control={form.control} name="password" render={({ field }) => <FormItem><div className="flex items-center"><FormLabel>Password</FormLabel><Link href="/forgot-password" className="ml-auto inline-block text-sm underline">Forgot your password?</Link></div><FormControl><Input type="password" placeholder="••••••••" {...field} disabled={isPending} /></FormControl><FormMessage /></FormItem>} /><Button type="submit" className="w-full" disabled={isPending}>{loginMutation.isPending && <Loader2 className="me-2 h-4 w-4 animate-spin" />}Login</Button><Button variant="outline" className="w-full" type="button" onClick={() => googleSignInMutation.mutate()} disabled={isPending}>{googleSignInMutation.isPending ? <Loader2 className="me-2 h-4 w-4 animate-spin" /> : <svg className="me-2 h-4 w-4" aria-hidden="true" focusable="false" data-prefix="fab" data-icon="google" role="img" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 488 512"><path fill="currentColor" d="M488 261.8C488 403.3 391.1 504 248 504 110.8 504 0 393.2 0 256S110.8 8 248 8c66.8 0 126 21.2 172.4 56.2l-62.8 55.7C334.3 88.2 294.2 72 248 72 165.2 72 96 141.2 96 224s69.2 152 152 152c86.4 0 142-51.7 148" /></svg>}Login with Google</Button><Button variant="outline" className="w-full" type="button" onClick={() => router.push('/phone-auth')} disabled={isPending}><Phone className="me-2 h-4 w-4" />Sign in with Phone</Button><div className="relative my-2"><div className="absolute inset-0 flex items-center"><span className="w-full border-t" /></div><div className="relative flex justify-center text-xs uppercase"><span className="bg-background px-2 text-muted-foreground">Or continue without an account</span></div></div><Button variant="secondary" className="w-full" type="button" onClick={handleGuestLogin} disabled={isPending}>Continue as Guest</Button><div className="mt-4 text-center text-sm">Don&apos;t have an account? <Link href="/signup" className="underline">Sign up</Link></div></form></Form>;
}
"}

{"file_path":"src/components/writing-tools/MarkdownToWordTool.tsx","overwrite":true,"initial_content":"'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { Loader2 } from 'lucide-react';
import { useState, type ComponentPropsWithoutRef } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { z } from 'zod';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { useToast } from '@/hooks/util/use-toast';
import dynamic from 'next/dynamic';
import { DocxTemplateKey, templates } from '@/modules/ai-content/infrastructure/exporters/DocxStyles';
import { apiService } from '@/infrastructure/api/ApiService';

const FileWord = dynamic<ComponentPropsWithoutRef<typeof Loader2>>(() => import('lucide-react').then((mod) => mod.FileText), { ssr: false });
const markdownToWordSchema = z.object({ markdown: z.string().min(10, 'Markdown content must be at least 10 characters long.'), fileName: z.string().min(1, 'File name is required.').regex(/^[a-zA-Z0-9_-]+$/, 'File name can only contain letters, numbers, underscores, and hyphens.'), template: z.enum(['modern', 'classic', 'academic']), pageNumbers: z.boolean().default(true), addCoverPage: z.boolean().default(false), coverPageMarkdown: z.string().optional(), isRtl: z.boolean().default(false) });
type MarkdownToWordFormValues = z.infer<typeof markdownToWordSchema>;

export function MarkdownToWordTool() {
  const { toast } = useToast();
  const [isConverting, setIsConverting] = useState(false);
  const form = useForm<MarkdownToWordFormValues>({ resolver: zodResolver(markdownToWordSchema), defaultValues: { markdown: '# Hello World\n\nThis is a sample markdown document.', fileName: 'document', template: 'modern', pageNumbers: true, addCoverPage: false, coverPageMarkdown: '# My Document Title\n\nBy John Doe\n\n{currentDate}', isRtl: false } });
  const addCoverPage = form.watch('addCoverPage');

  async function onSubmit(data: MarkdownToWordFormValues) {
    setIsConverting(true);
    try {
      const options = { styles: templates[data.template as DocxTemplateKey].styles, customStyles: templates[data.template as DocxTemplateKey].customStyles, pageNumbers: data.pageNumbers, coverPageMarkdown: data.addCoverPage ? data.coverPageMarkdown : undefined, isRtl: data.isRtl };
      const blob = await apiService<{ markdown: string; fileName: string; options: typeof options }, Blob>({ endpoint: '/api/export/docx', method: 'POST', data: { markdown: data.markdown, fileName: data.fileName, options }, responseType: 'blob' });
      const { saveAs } = await import('file-saver');
      saveAs(blob, `${data.fileName}.docx`);
      toast({ title: 'Conversion Successful', description: `Your file ${data.fileName}.docx has been downloaded.` });
    } catch (error) {
      console.error('Failed to convert markdown to word:', error);
      toast({ title: 'Conversion Failed', description: error instanceof Error ? error.message : String(error), variant: 'destructive' });
    } finally { setIsConverting(false); }
  }

  return <Card><CardHeader><CardTitle>Markdown to Word Converter</CardTitle><CardDescription>Easily convert your markdown documents into styled .docx files, with support for different page orientations.</CardDescription></CardHeader><CardContent><form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6"><div className="space-y-2"><Label htmlFor="markdown-input">Markdown Content</Label><Textarea id="markdown-input" {...form.register('markdown')} placeholder="Enter your markdown here..." className="min-h-[300px] font-mono" disabled={isConverting} />{form.formState.errors.markdown && <p className="text-sm text-destructive">{form.formState.errors.markdown.message}</p>}</div><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><div className="space-y-2"><Label htmlFor="fileName-input">File Name</Label><Input id="fileName-input" {...form.register('fileName')} placeholder="e.g., my-report" disabled={isConverting} />{form.formState.errors.fileName && <p className="text-sm text-destructive">{form.formState.errors.fileName.message}</p>}</div><div className="space-y-2"><Label htmlFor="template-select">Document Template</Label><Select onValueChange={(value: DocxTemplateKey) => form.setValue('template', value as any)} defaultValue={form.getValues('template')} disabled={isConverting}><SelectTrigger id="template-select"><SelectValue placeholder="Select a template" /></SelectTrigger><SelectContent>{Object.keys(templates).map((key) => <SelectItem key={key} value={key}>{key.charAt(0).toUpperCase() + key.slice(1)}</SelectItem>)}</SelectContent></Select></div></div><div className="space-y-4 pt-2"><div className="flex items-center space-x-2"><Controller name="addCoverPage" control={form.control} render={({ field }) => <Checkbox id="addCoverPage" checked={field.value} onCheckedChange={field.onChange} disabled={isConverting} />} /><Label htmlFor="addCoverPage" className="cursor-pointer">Add a cover page</Label></div>{addCoverPage && <div className="space-y-2 pl-6 border-s-2 ms-3"><Label htmlFor="cover-page-markdown-input">Cover Page Markdown</Label><Textarea id="cover-page-markdown-input" {...form.register('coverPageMarkdown')} placeholder="Enter markdown for your cover page..." className="min-h-[150px] font-mono" disabled={isConverting} /></div>}</div><div className="flex items-center space-x-2 pt-2"><Controller name="pageNumbers" control={form.control} render={({ field }) => <Checkbox id="pageNumbers" checked={field.value} onCheckedChange={field.onChange} disabled={isConverting} />} /><Label htmlFor="pageNumbers" className="cursor-pointer">Add page numbers to footer</Label></div><div className="flex items-center space-x-2 pt-2"><Controller name="isRtl" control={form.control} render={({ field }) => <Checkbox id="isRtl" checked={field.value} onCheckedChange={field.onChange} disabled={isConverting} />} /><Label htmlFor="isRtl" className="cursor-pointer">Enable Right-to-Left (RTL) text direction (for Arabic, Hebrew, etc.)</Label></div><Button type="submit" disabled={isConverting} className="w-full">{isConverting ? <Loader2 className="me-2 h-4 w-4 animate-spin" /> : <FileWord className="me-2 h-4 w-4" />}{isConverting ? 'Converting...' : 'Convert and Download .docx'}</Button></form></CardContent></Card>;
}
"}

{"file_path":"src/components/admin/document-indexer/FileUploadZone.tsx","overwrite":true,"initial_content":"'use client';

import React, { useState, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Upload, X, Loader2, CheckCircle, AlertCircle } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import type { IndexingOptions } from './DocumentIndexerInterface';
import { apiService } from '@/infrastructure/api/ApiService';

interface FileWithPreview extends File { preview?: string; status?: 'pending' | 'uploading' | 'success' | 'error'; error?: string; chunksCreated?: number; }
interface Props { indexingOptions: IndexingOptions; onOptionsChange: (options: IndexingOptions) => void; }

export function FileUploadZone({ indexingOptions, onOptionsChange }: Props) {
  const [files, setFiles] = useState<FileWithPreview[]>([]);
  const [uploading, setUploading] = useState(false);
  const [dragActive, setDragActive] = useState(false);

  const handleDrag = useCallback((e: React.DragEvent) => { e.preventDefault(); e.stopPropagation(); if (e.type === 'dragenter' || e.type === 'dragover') setDragActive(true); else if (e.type === 'dragleave') setDragActive(false); }, []);
  const handleDrop = useCallback((e: React.DragEvent) => { e.preventDefault(); e.stopPropagation(); setDragActive(false); if (e.dataTransfer.files && e.dataTransfer.files[0]) handleFiles(e.dataTransfer.files); }, []);
  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files && e.target.files[0]) handleFiles(e.target.files); };
  const handleFiles = (fileList: FileList) => setFiles((prev) => [...prev, ...Array.from(fileList).map((file) => Object.assign(file, { status: 'pending' as const }))]);
  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));

  const uploadFiles = async () => {
    if (!indexingOptions.projectId.trim()) { alert('Please enter a Project ID'); return; }
    setUploading(true);

    for (let i = 0; i < files.length; i++) {
      if (files[i].status !== 'pending') continue;
      setFiles((prev) => prev.map((f, idx) => idx === i ? { ...f, status: 'uploading' as const } : f));
      try {
        const formData = new FormData();
        formData.append('file', files[i]);
        formData.append('projectId', indexingOptions.projectId);
        formData.append('chunkSize', String(indexingOptions.chunkSize));
        formData.append('overlap', String(indexingOptions.overlap));
        formData.append('type', indexingOptions.type);
        if (indexingOptions.userId) formData.append('userId', indexingOptions.userId);

        const result = await apiService<FormData, { success?: boolean; chunksCreated?: number; error?: string }>({
          endpoint: '/api/admin/rag/index', method: 'POST', data: formData, isFormData: true,
        });

        if (result.success) {
          setFiles((prev) => prev.map((f, idx) => idx === i ? { ...f, status: 'success' as const, chunksCreated: result.chunksCreated } : f));
        } else {
          setFiles((prev) => prev.map((f, idx) => idx === i ? { ...f, status: 'error' as const, error: result.error || 'Upload failed' } : f));
        }
      } catch (error) {
        setFiles((prev) => prev.map((f, idx) => idx === i ? { ...f, status: 'error' as const, error: error instanceof Error ? error.message : 'Unknown error' } : f));
      }
    }
    setUploading(false);
  };

  const formatFileSize = (bytes: number) => { if (bytes === 0) return '0 Bytes'; const k = 1024; const sizes = ['Bytes', 'KB', 'MB', 'GB']; const i = Math.floor(Math.log(bytes) / Math.log(k)); return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i]; };
  const getFileIcon = (file: File) => { if (!file?.name) return '📎'; const filename = file.name.toLowerCase(); if (filename.endsWith('.pdf')) return '📄'; if (filename.endsWith('.docx') || filename.endsWith('.doc')) return '📝'; if (filename.endsWith('.txt') || filename.endsWith('.md')) return '📃'; if (file.type?.includes('pdf')) return '📄'; if (file.type?.includes('word')) return '📝'; if (file.type?.includes('text')) return '📃'; return '📎'; };
  const pendingCount = files.filter((f) => f.status === 'pending').length; const successCount = files.filter((f) => f.status === 'success').length; const errorCount = files.filter((f) => f.status === 'error').length;

  return <Card><CardHeader><CardTitle>Upload Documents</CardTitle><CardDescription>Drag and drop files or click to browse. Supported: PDF, DOCX, TXT, MD</CardDescription></CardHeader><CardContent className="space-y-6"><div className="space-y-2"><Label htmlFor="projectId">Project ID <span className="text-destructive">*</span></Label><Input id="projectId" placeholder="e.g., my-project, documentation, research" value={indexingOptions.projectId} onChange={(e) => onOptionsChange({ ...indexingOptions, projectId: e.target.value })} disabled={uploading} /><p className="text-xs text-muted-foreground">Documents will be indexed under this project for filtering</p></div><div className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${dragActive ? 'border-primary bg-primary/5' : 'border-muted-foreground/25 hover:border-muted-foreground/50'}`} onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}><Upload className="mx-auto h-12 w-12 text-muted-foreground mb-4" /><h3 className="text-lg font-semibold mb-2">Drop files here</h3><p className="text-sm text-muted-foreground mb-4">or click to select files</p><input type="file" id="file-input" className="hidden" multiple accept=".pdf,.docx,.txt,.md" onChange={handleFileInput} disabled={uploading} /><Button onClick={() => document.getElementById('file-input')?.click()} variant="outline" disabled={uploading}>Browse Files</Button></div>{files.length > 0 && <div className="space-y-3"><div className="flex items-center justify-between"><h3 className="font-semibold">Selected Files ({files.length})</h3>{successCount > 0 && <Badge variant="default">{successCount} indexed</Badge>}</div><div className="space-y-2">{files.map((file, index) => <div key={index} className="flex items-center gap-3 p-3 rounded-lg border bg-muted/50"><div className="text-2xl">{getFileIcon(file)}</div><div className="flex-1 min-w-0"><div className="flex items-center gap-2"><p className="font-medium truncate">{file.name}</p>{file.status === 'uploading' && <Loader2 className="h-4 w-4 animate-spin text-primary" />}{file.status === 'success' && <CheckCircle className="h-4 w-4 text-green-600" />}{file.status === 'error' && <AlertCircle className="h-4 w-4 text-destructive" />}</div><div className="flex items-center gap-2 text-xs text-muted-foreground"><span>{formatFileSize(file.size)}</span>{file.chunksCreated && <Badge variant="outline" className="text-xs">{file.chunksCreated} chunks</Badge>}</div>{file.error && <p className="text-xs text-destructive mt-1">{file.error}</p>}</div>{file.status === 'pending' && <Button onClick={() => removeFile(index)} variant="ghost" size="sm" disabled={uploading}><X className="h-4 w-4" /></Button>}</div>)}</div></div>}{files.length > 0 && pendingCount > 0 && <div className="space-y-3"><Button onClick={uploadFiles} className="w-full" disabled={uploading || !indexingOptions.projectId.trim()}>{uploading ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" />Indexing {files.findIndex((f) => f.status === 'uploading') + 1} of {pendingCount}...</> : <><Upload className="h-4 w-4 mr-2" />Index {pendingCount} Document{pendingCount !== 1 ? 's' : ''}</>}</Button>{errorCount > 0 && <Alert variant="destructive"><AlertCircle className="h-4 w-4" /><AlertDescription>{errorCount} file{errorCount !== 1 ? 's' : ''} failed to index. Check the errors above.</AlertDescription></Alert>}</div>}{files.length > 0 && pendingCount === 0 && <Alert><CheckCircle className="h-4 w-4" /><AlertDescription>All files processed! {successCount} successfully indexed, {errorCount} failed.</AlertDescription></Alert>}</CardContent></Card>;
}
"}

{"file_path":"src/components/admin/rag-tester/RAGQueryTesterInterface.tsx","overwrite":true,"initial_content":"'use client';

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Search, Loader2, CheckCircle, Clock, Database, Zap } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { apiService } from '@/infrastructure/api/ApiService';

interface SearchResult { content: string; score: number; sourceFile?: string; projectId?: string; type: string; chunkIndex: number; }
interface SearchResponse { context: string; sources: SearchResult[]; query: string; searchTime?: number; cacheHit?: boolean; }

export function RAGQueryTesterInterface() {
  const [query, setQuery] = useState(''); const [projectId, setProjectId] = useState(''); const [topK, setTopK] = useState(5); const [minScore, setMinScore] = useState(0.5); const [useCache, setUseCache] = useState(true); const [rerank, setRerank] = useState(false); const [rerankStrategy, setRerankStrategy] = useState<string>('hybrid'); const [loading, setLoading] = useState(false); const [results, setResults] = useState<SearchResponse | null>(null); const [error, setError] = useState<string | null>(null); const [searchTime, setSearchTime] = useState<number | null>(null);
  const handleSearch = async () => { if (!query.trim()) { setError('Please enter a query'); return; } setLoading(true); setError(null); const startTime = Date.now(); try { const data = await apiService<{ query: string; projectId?: string; topK: number; minScore: number; useCache: boolean; rerank: boolean; rerankStrategy: string }, SearchResponse>({ endpoint: '/api/admin/rag/test-query', method: 'POST', data: { query, projectId: projectId || undefined, topK, minScore, useCache, rerank, rerankStrategy } }); setResults(data); setSearchTime(Date.now() - startTime); } catch (err) { setError(err instanceof Error ? err.message : 'Search failed'); setResults(null); } finally { setLoading(false); } };
  const sampleQueries = ['What is quantum computing?', 'Explain TypeScript utility types', 'How does machine learning work?', 'What are vector databases?'];
  return <div className="space-y-6"><Card><CardHeader><CardTitle>Search Query</CardTitle><CardDescription>Enter your query to test RAG search with Ollama + Qdrant</CardDescription></CardHeader><CardContent className="space-y-6"><div className="space-y-2"><Label htmlFor="query">Query</Label><div className="flex gap-2"><Input id="query" placeholder="Enter your search query..." value={query} onChange={(e) => setQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && !loading && handleSearch()} disabled={loading} className="flex-1" /><Button onClick={handleSearch} disabled={loading || !query.trim()}>{loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}</Button></div></div><div className="space-y-2"><Label>Quick Tests:</Label><div className="flex flex-wrap gap-2">{sampleQueries.map((sample, idx) => <Badge key={idx} variant="outline" className="cursor-pointer hover:bg-primary hover:text-primary-foreground" onClick={() => setQuery(sample)}>{sample}</Badge>)}</div></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label htmlFor="projectId">Project ID (Optional)</Label><Input id="projectId" placeholder="Filter by project" value={projectId} onChange={(e) => setProjectId(e.target.value)} disabled={loading} /></div><div className="space-y-2"><Label>Re-ranking Strategy</Label><Select value={rerankStrategy} onValueChange={setRerankStrategy} disabled={loading || !rerank}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="hybrid">Hybrid (Semantic + Keyword)</SelectItem><SelectItem value="cross-encoder">Cross-Encoder (Most Accurate)</SelectItem><SelectItem value="bm25">BM25 (Keyword Only)</SelectItem><SelectItem value="reciprocal-rank-fusion">RRF (Ensemble)</SelectItem></SelectContent></Select></div></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Top K Results: {topK}</Label><Slider value={[topK]} onValueChange={([value]) => setTopK(value)} min={1} max={20} step={1} disabled={loading} /></div><div className="space-y-2"><Label>Min Score: {minScore.toFixed(2)}</Label><Slider value={[minScore]} onValueChange={([value]) => setMinScore(value)} min={0} max={1} step={0.05} disabled={loading} /></div></div><div className="flex items-center gap-6"><div className="flex items-center space-x-2"><Switch id="cache" checked={useCache} onCheckedChange={setUseCache} disabled={loading} /><Label htmlFor="cache">Use Cache</Label></div><div className="flex items-center space-x-2"><Switch id="rerank" checked={rerank} onCheckedChange={setRerank} disabled={loading} /><Label htmlFor="rerank">Re-ranking</Label></div></div></CardContent></Card>{searchTime !== null && results && <div className="grid gap-4 md:grid-cols-4"><Card><CardContent className="pt-6"><div className="flex items-center gap-2"><Clock className="h-4 w-4 text-muted-foreground" /><div><div className="text-2xl font-bold">{searchTime}ms</div><div className="text-xs text-muted-foreground">Search Time</div></div></div></CardContent></Card><Card><CardContent className="pt-6"><div className="flex items-center gap-2"><Database className="h-4 w-4 text-muted-foreground" /><div><div className="text-2xl font-bold">{results.sources.length}</div><div className="text-xs text-muted-foreground">Results Found</div></div></div></CardContent></Card><Card><CardContent className="pt-6"><div className="flex items-center gap-2">{results.cacheHit ? <CheckCircle className="h-4 w-4 text-green-500" /> : <Zap className="h-4 w-4 text-muted-foreground" />}<div><div className="text-2xl font-bold">{results.cacheHit ? 'Yes' : 'No'}</div><div className="text-xs text-muted-foreground">Cache Hit</div></div></div></CardContent></Card><Card><CardContent className="pt-6"><div className="flex items-center gap-2"><div><div className="text-2xl font-bold">{results.sources.length > 0 ? results.sources[0].score.toFixed(3) : 'N/A'}</div><div className="text-xs text-muted-foreground">Top Score</div></div></div></CardContent></Card></div>}{error && <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert>}{results && results.sources.length > 0 && <Card><CardHeader><CardTitle>Search Results ({results.sources.length})</CardTitle><CardDescription>Showing top {results.sources.length} results ranked by relevance</CardDescription></CardHeader><CardContent className="space-y-3">{results.sources.map((result, idx) => <Card key={idx} className="border-l-4 border-l-primary"><CardContent className="pt-4"><div className="space-y-3"><div className="flex items-start justify-between gap-4"><div className="flex flex-wrap items-center gap-2"><Badge variant="default" className="font-mono">#{idx + 1}</Badge><Badge variant="secondary">Score: {result.score.toFixed(3)}</Badge>{result.sourceFile && <Badge variant="outline">📄 {result.sourceFile}</Badge>}{result.projectId && <Badge variant="outline">🏷️ {result.projectId}</Badge>}<Badge variant="outline">{result.type}</Badge><Badge variant="outline" className="font-mono text-xs">Chunk {result.chunkIndex}</Badge></div></div><div className="rounded-md bg-muted/50 p-4"><p className="text-sm whitespace-pre-wrap leading-relaxed">{result.content}</p></div><div className="flex items-center gap-2"><div className="flex-1 h-2 bg-muted rounded-full overflow-hidden"><div className="h-full bg-primary transition-all" style={{ width: `${result.score * 100}%` }} /></div><span className="text-xs text-muted-foreground">{(result.score * 100).toFixed(1)}% match</span></div></div></CardContent></Card>)}</CardContent></Card>}{results && results.sources.length === 0 && <Card><CardContent className="py-12"><div className="text-center text-muted-foreground"><p className="text-lg font-medium mb-2">No results found</p><p className="text-sm">Try adjusting your query, lowering the min score threshold, or checking if documents are indexed.</p></div></CardContent></Card>}{!loading && !results && !error && <Card><CardContent className="py-12"><div className="text-center text-muted-foreground"><Search className="h-12 w-12 mx-auto mb-4 opacity-50" /><p className="text-lg font-medium mb-2">Ready to search</p><p className="text-sm">Enter a query above to test the RAG system with real-time results</p></div></CardContent></Card>}</div>;
}
"}

